window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbl-001',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-01T15:10:00',views:275,tags:['eigen geld','schenking','financieringsopzet'],beste:'vbl-001-a1',
  titel:'Schenking en spaargeld apart tonen als eigen geld in eBlinqx Hypotheekadvies',
  body:`Mijn klanten brengen eigen geld in uit spaargeld en een schenking van de ouders. In de financieringsopzet zie ik alleen één totaalbedrag eigen middelen. Kan ik de herkomst apart laten zien, zodat het rapport en het dossier duidelijk zijn?`,
  antwoorden:[
   {id:'vbl-001-a1',auteur:'u6',datum:'2025-10-02T03:57:00',rA:{u4:4,u1:5,u7:5,u3:5},rAdv:{u1:5,u7:5,u3:5},body:`Ja, eigen geld kun je in eBlinqx Hypotheekadvies specificeren naar herkomst, zoals spaargeld, schenking of beleggingen. Op de supportsite staat daar een apart artikel over ("Hoe specificeer ik eigen geld"). Vul per bron het bedrag in, dan sluit het totaal weer aan op de opzet. Controleer daarna of het totaal eigen geld gelijk is aan wat je in de berekening verwacht.`},
   {id:'vbl-001-a2',auteur:'u5',datum:'2025-10-02T10:36:00',rA:{u7:5,u8:3,u1:4,u3:5},rAdv:{u8:3,u1:4,u3:5},body:`Aanvulling vanuit de praktijk: leg in het dossier ook vast waarmee de herkomst is aangetoond, bijvoorbeeld een bankafschrift en een schenkingsovereenkomst. Bespreek met de klant of de schenking fiscale gevolgen heeft en verwijs voor de actuele vrijstellingen naar de geldende regels. Controleer ook welke bewijsstukken de geldverstrekker vraagt, want dat verschilt.`}
  ]},
 {id:'vbl-002',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-04T10:40:00',views:44,tags:['overbrugging','draagplicht','handmatige invoer'],beste:'vbl-002-a1',
  titel:'Handmatig overbruggingsbedrag telt niet mee in de draagplicht',
  body:`Ik heb het overbruggingskrediet handmatig aangepast omdat de verwachte verkoopprijs lager uitvalt. Nu klopt de verdeling draagplicht tussen de partners niet meer. Is dat een fout in de software of doe ik iets verkeerd?`,
  antwoorden:[
   {id:'vbl-002-a1',auteur:'u6',datum:'2025-10-05T09:37:00',rA:{u2:4,u1:4},rAdv:{u2:4,u1:4},body:`Dat is bekend gedrag en geen storing: een handmatig ingevoerd overbruggingsbedrag wordt niet meegenomen in de draagplicht van de financieringsopzet. De supportsite heeft daar een apart artikel over. Wil je dat de draagplicht automatisch klopt, laat het overbruggingsbedrag dan zoveel mogelijk door de software berekenen via het overbruggingspercentage onder Eigen geld. Kies je toch voor handmatig, leg dan de verdeling en de onderbouwing vast in de motivatie.`},
   {id:'vbl-002-a2',auteur:'u4',datum:'2025-10-05T12:20:00',rA:{},rAdv:{},body:`Ik zet in zo een geval een korte notitie in het dossier met de berekening van de overbrugging en hoe de partners de lasten dragen. Dan is voor een collega of de compliance-check later te volgen waarom de opzet afwijkt van de standaard.`}
  ]},
 {id:'vbl-003',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-08T15:10:00',views:285,tags:['afronding','financieringsopzet','leningdelen'],beste:'vbl-003-a1',
  titel:'Afrondingsverschil van een paar euro in de financieringsopzet',
  body:`Mijn financieringsopzet sluit niet: er blijft een verschil van een paar euro over tussen de totale investering en de financiering. Ik wil het rapport zo niet naar de klant sturen. Hoe lossen jullie dat op?`,
  antwoorden:[
   {id:'vbl-003-a1',auteur:'u6',datum:'2025-10-09T13:46:00',rA:{u1:3,u2:5},rAdv:{u1:3,u2:5},body:`Een afrondingsverschil los je op via de leningdelen: corrigeer het verschil op het kleinste leningdeel, zodat de optelsom weer aansluit. Er staat een artikel over op de supportsite van eBlinqx Hypotheekadvies. Let erop dat je bij een NHG-financiering niet boven de toegestane grens uitkomt door de correctie. Controleer daarna de maandlasten in het rapport nog even.`},
   {id:'vbl-003-a2',auteur:'u1',datum:'2025-10-10T03:31:00',rA:{u4:3,u7:3},rAdv:{u4:3},body:`Ik rond de hoofdsom vaak naar boven af op een rond bedrag en laat het restant als extra eigen geld of buffer zien. Overleg wel met de klant, want dan verandert de inbreng eigen middelen. Leg de keuze vast in de motivatie.`}
  ]},
 {id:'vbl-004',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-11T14:35:00',views:103,tags:['weergave','financieringsopzet','eblinqx'],beste:'vbl-004-a1',
  titel:'Financieringsopzet in twee kolommen tonen voor vergelijking',
  body:`Een collega liet een financieringsopzet zien met twee kolommen naast elkaar. Bij mij zie ik maar één kolom. Hoe schakel ik dat om?`,
  antwoorden:[
   {id:'vbl-004-a1',auteur:'u6',datum:'2025-10-12T00:37:00',rA:{u3:4,u7:3},rAdv:{u3:4},body:`Je kunt in eBlinqx Hypotheekadvies wisselen tussen een 1- en 2-kolomsweergave van de financieringsopzet. De stappen staan in het supportartikel over de kolomsweergave. De weergave verandert niets aan de berekening zelf, alleen aan hoe het op het scherm staat. Gebruik de 2-kolomsweergave vooral als je situaties naast elkaar wilt bespreken met de klant.`}
  ]},
 {id:'vbl-005',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-15T17:20:00',views:103,tags:['geldverstrekker','financieringsopzet','weergave'],beste:null,
  titel:'Geldverstrekker staat niet in de financieringsopzet',
  body:`Ik heb een berekening gemaakt, maar de naam van de geldverstrekker verschijnt niet in de financieringsopzet. In het rapport wil ik dat wel zien. Waar zit dat?`,
  antwoorden:[
   {id:'vbl-005-a1',auteur:'u6',datum:'2025-10-15T22:38:00',rA:{u4:5,u7:5},rAdv:{u4:5,u7:5},body:`Daar is een supportartikel over: "Waarom wordt de geldverstrekker niet getoond in de financieringsopzet". Meestal heeft het te maken met de manier waarop het product aan de leningdelen is gekoppeld. Controleer of je bij de leningdelen een product van een geldverstrekker hebt geselecteerd en niet alleen een vrije invoer. Lukt het daarna nog niet, stuur dan het dossiernummer naar support.`},
   {id:'vbl-005-a2',auteur:'u4',datum:'2025-10-16T05:48:00',rA:{u7:4},rAdv:{u7:4},body:`Bij mij lag het aan een leningdeel dat ik als vrij leningdeel had toegevoegd voor een vergelijking. Nadat ik het product opnieuw koos, stond de naam er weer.`}
  ]},
 {id:'vbl-006',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-19T11:10:00',views:359,tags:['erfpacht','afkoop','financieringsopzet'],beste:'vbl-006-a1',
  titel:'Afkoop erfpacht meenemen in de financieringsopzet',
  body:`De klant koopt een appartement met erfpacht en wil de canon eeuwigdurend afkopen bij de aankoop. Hoe neem ik de afkoopsom op in de financieringsopzet? En telt dat mee in de fiscale berekening?`,
  antwoorden:[
   {id:'vbl-006-a1',auteur:'u6',datum:'2025-10-20T08:17:00',rA:{u5:4,u3:4},rAdv:{u5:4,u3:4},body:`De afkoopsom voeg je toe als eigen kostenpost via "Voeg extra veld toe" onder Kosten van de woning. Er is ook een specifiek supportartikel over erfpacht afkoop in de financieringsopzet. Let op: handmatige posten tellen mee in het totaal, maar niet automatisch in de fiscale componenten. Leg in de motivatie vast hoe je de fiscale behandeling hebt beoordeeld.`},
   {id:'vbl-006-a2',auteur:'u5',datum:'2025-10-20T18:24:00',rA:{u3:4,u7:3},rAdv:{u7:3},body:`Fiscaal hangt het af van de situatie of de afkoop tot de verwervingskosten van de eigen woning hoort. Toets dat aan de actuele regels en leg je conclusie vast. Controleer daarnaast de voorwaarden van de geldverstrekker over erfpacht, zoals de resterende looptijd en de wijze van waardering in het taxatierapport.`},
   {id:'vbl-006-a3',auteur:'u2',datum:'2025-10-21T00:33:00',rA:{u3:4,u5:5},rAdv:{u3:4,u5:5},body:`Bespreek ook de lange termijn met de klant: afkopen tegenover blijven betalen van canon. Een korte vergelijking in het dossier helpt om te laten zien dat je de keuze samen hebt afgewogen.`}
  ]},
 {id:'vbl-007',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-22T08:55:00',views:142,tags:['krediet','inlossen','toetsing'],beste:'vbl-007-a2',
  titel:'Krediet aflossen via de nieuwe hypotheek: hoe invoeren?',
  body:`Een klant heeft een doorlopend krediet dat bij het passeren wordt afgelost uit de hypotheek. Ik weet niet goed waar ik dat invoer zodat het zowel in de toets als in de opzet goed staat. Wie heeft dit eerder gedaan?`,
  antwoorden:[
   {id:'vbl-007-a1',auteur:'u6',datum:'2025-10-22T20:59:00',rA:{u4:4,u2:5},rAdv:{u4:4,u2:5},body:`Op de supportsite staat het artikel "Hoe voer ik kredieten in die via de hypotheek worden ingelost". Kort: je registreert het krediet bij de verplichtingen en geeft aan dat het tijdens het passeren wordt afgelost, zodat het in de opzet als kostenpost meekomt. Controleer daarna of de last van het krediet niet meer in de toetsing meetelt.`},
   {id:'vbl-007-a2',auteur:'u1',datum:'2025-10-23T03:56:00',rA:{u7:4,u6:3},rAdv:{u7:4,u6:3},body:`Let op dat niet elke geldverstrekker accepteert dat een krediet uit de hypotheek wordt afgelost, en de fiscale behandeling van dat deel wijkt af. Ik maak er altijd een apart leningdeel van in box 3. Leg de aflossingsverplichting vast en vraag tijdig de aflosnota op.`}
  ]},
 {id:'vbl-008',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-26T14:45:00',views:45,tags:['afkoopwaarde','polis','eigen geld'],beste:'vbl-008-a2',
  titel:'Afkoopwaarde van een polis als eigen geld',
  body:`De klant wil een lopende kapitaalverzekering afkopen en de afkoopwaarde inbrengen. Moet ik dat als eigen geld opnemen of op een andere plek in de opzet?`,
  antwoorden:[
   {id:'vbl-008-a1',auteur:'u6',datum:'2025-10-27T10:26:00',rA:{u4:5,u8:4,u1:3,u5:3},rAdv:{u4:5,u8:4},body:`Hiervoor is een supportartikel: "Hoe verwerk ik een polis afkoopwaarde in de financieringsopzet". Neem het bedrag op als eigen inbreng zodat het totaal sluit. Gebruik een recente opgave van de afkoopwaarde en leg die in het dossier.`},
   {id:'vbl-008-a2',auteur:'u3',datum:'2025-10-27T12:08:00',rA:{u6:4,u5:3},rAdv:{u5:3},body:`Voordat de klant afkoopt: kijk of er een overlijdensrisicodekking aan de polis hangt die wegvalt. Dan moet je dat risico mogelijk op een andere manier afdekken. Leg vast dat je dat besproken hebt.`},
   {id:'vbl-008-a3',auteur:'u5',datum:'2025-10-27T19:52:00',rA:{u8:4},rAdv:{u8:4},body:`Check ook de fiscale status van de polis voordat je afkoopt, zeker bij oude polissen met een bijzonder fiscaal regime. Verwijs naar de geldende regels en laat het zo nodig door een fiscalist bevestigen.`}
  ]},
 {id:'vbl-009',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-30T13:25:00',views:546,tags:['box 1','box 3','leningdelen'],beste:'vbl-009-a1',
  titel:'Gemengd leningdeel box 1 en box 3 geeft rare uitkomsten',
  body:`In een oversluitdossier heb ik één leningdeel dat deels aftrekbaar en deels niet aftrekbaar is. De netto maandlast lijkt niet te kloppen. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbl-009-a1',auteur:'u6',datum:'2025-10-30T18:09:00',rA:{u3:5,u7:4},rAdv:{u7:4},body:`Elk leningdeel valt in eBlinqx volledig in één box; gemengde leningdelen worden niet ondersteund en geven verkeerde berekeningen en fiscale rapportages. Splits het in twee leningdelen: één deel in box 1 en één deel in box 3. Pas daarna de hoofdsommen per deel aan.`},
   {id:'vbl-009-a2',auteur:'u5',datum:'2025-10-31T00:24:00',rA:{u8:5,u3:3},rAdv:{u8:5},body:`Daarbij is het belangrijk dat je de eigenwoningschuld goed vaststelt, inclusief een eventuele eigenwoningreserve uit het verleden. Leg je berekening vast in het dossier. Bij twijfel over het fiscale verleden vraag ik de klant om oude aangiften en aflosnota's.`}
  ]},
 {id:'vbl-010',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-02T15:15:00',views:246,tags:['notariskosten','tarieven','instellingen'],beste:'vbl-010-a1',
  titel:'Notariskosten staan standaard op een verkeerd bedrag',
  body:`Bij elke nieuwe berekening komen de notariskosten op een bedrag uit dat niet past bij de notaris waar wij mee werken. Ik pas het steeds handmatig aan. Kan dat centraal?`,
  antwoorden:[
   {id:'vbl-010-a1',auteur:'u6',datum:'2025-11-03T05:53:00',rA:{u2:4,u7:5},rAdv:{u2:4,u7:5},body:`Ja, vaste kosten zoals notariskosten stel je centraal in via Instellingen > eBlinqx Hypotheekadvies > Tarieven, bijvoorbeeld Hypotheekakte notaris en Leveringsakte notaris. Daar heb je mogelijk beheerrechten voor nodig. Na aanpassing gelden de bedragen voor nieuwe berekeningen; controleer bestaande dossiers apart.`},
   {id:'vbl-010-a2',auteur:'u4',datum:'2025-11-03T17:01:00',rA:{u6:5,u1:3},rAdv:{u1:3},body:`Wij hebben dit bij ons kantoor één keer goed ingesteld en daarna jaarlijks gecontroleerd met een offerte van de notaris. Voor een specifieke klant blijf je het per dossier aanpassen als de notaris afwijkt.`}
  ]},
 {id:'vbl-011',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-06T14:05:00',views:272,tags:['advieskosten','bemiddelingskosten','hdn'],beste:'vbl-011-a2',
  titel:'Advieskosten en bemiddelingskosten apart houden voor de aanvraag',
  body:`Wij rekenen één bedrag aan advies- en bemiddelingskosten. Moet ik dat in de software splitsen, en waarom eigenlijk?`,
  antwoorden:[
   {id:'vbl-011-a1',auteur:'u6',datum:'2025-11-06T22:23:00',rA:{u5:4,u3:4,u8:5},rAdv:{u5:4},body:`Ja, vul advieskosten en bemiddelingskosten apart in en houd ze gescheiden. Dat is vereist voor HDN-aanvragen. Gebruik dezelfde verdeling als op je vergelijkingskaart, in je opdrachtbevestiging en op je factuur.`},
   {id:'vbl-011-a2',auteur:'u8',datum:'2025-11-07T07:40:00',rA:{u6:5,u3:4},rAdv:{u6:5},body:`Vanuit compliance: zorg dat de verdeling in de opzet, de vergelijkingskaart, de opdrachtbevestiging en de factuur overeenkomt. Een verschil daartussen roept vragen op bij een controle. Leg ook vast dat je de kosten vooraf met de klant hebt besproken.`}
  ]},
 {id:'vbl-012',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-10T09:55:00',views:508,tags:['familiehypotheek','hdn','toetsing'],beste:'vbl-012-a1',
  titel:'Familiehypotheek combineren met een reguliere hypotheek in de software',
  body:`De ouders lenen een deel aan het kind, de rest gaat via een geldverstrekker. Hoe verwerk ik de familiehypotheek zodat de toets klopt en de aanvraag ook? Ik krijg het niet in één berekening goed.`,
  antwoorden:[
   {id:'vbl-012-a1',auteur:'u6',datum:'2025-11-11T07:54:00',rA:{u3:3,u7:4,u2:4,u8:5},rAdv:{u3:3,u8:5},body:`Een familiehypotheek gaat niet via HDN. In combinatie met een reguliere hypotheek zijn soms twee berekeningen nodig: één voor de toetsing, met het familiebedrag als leningdeel, en één voor de aanvraag, met het familiebedrag als eigen middelen. Geef beide berekeningen een duidelijke naam zodat je ze niet door elkaar haalt.`},
   {id:'vbl-012-a2',auteur:'u5',datum:'2025-11-11T16:02:00',rA:{u7:3,u8:3},rAdv:{u8:3},body:`Controleer de voorwaarden van de geldverstrekker over hoe zij de lasten van de familielening meenemen in de toets. Leg de leningsovereenkomst, de rente-afspraken en de fiscale aspecten vast in het dossier. Verwijs voor de fiscale voorwaarden naar de actuele regels.`}
  ]},
 {id:'vbl-013',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-13T12:35:00',views:476,tags:['nieuwbouw','bouwdepot','financieringsopzet'],beste:null,
  titel:'Nieuwbouw: grondkosten en bouwdepot in de financieringsopzet',
  body:`Mijn eerste nieuwbouwdossier in eBlinqx. Grondkosten, aanneemsom, meerwerk en bouwrente: ik weet niet goed welke velden ik moet gebruiken. Is er een overzicht?`,
  antwoorden:[
   {id:'vbl-013-a1',auteur:'u6',datum:'2025-11-13T15:13:00',rA:{u7:3,u2:4,u8:3,u1:4},rAdv:{u2:4},body:`De nieuwbouwvariant van de financieringsopzet heeft aparte velden voor grondkosten, aanneemsom, meerwerk en bouwrente. Het kennisbankartikel over het aanpassen van de financieringsopzet bij deze categorie beschrijft alle varianten. Controleer na invoer of het bouwdepot aansluit op de koop-/aanneemovereenkomst.`},
   {id:'vbl-013-a2',auteur:'u4',datum:'2025-11-14T05:38:00',rA:{},rAdv:{},body:`Uit de praktijk: vraag de meerwerklijst vroeg op, die wordt vaak pas laat definitief. Kijk ook naar de dubbele lasten tijdens de bouw en hoe de geldverstrekker met bouwrente omgaat. Controleer de voorwaarden van de geldverstrekker over de looptijd van het bouwdepot.`}
  ]},
 {id:'vbl-014',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-17T15:15:00',views:21,tags:['verbouwing','verduurzaming','rapport'],beste:null,
  titel:'Verbouwing en energiebesparende maatregelen apart zichtbaar maken',
  body:`Klant koopt een woning en wil direct verbouwen en isoleren. Ik wil in het rapport laten zien welk deel voor verduurzaming is. Hoe doen jullie dat?`,
  antwoorden:[
   {id:'vbl-014-a1',auteur:'u1',datum:'2025-11-18T02:37:00',rA:{u6:5,u4:3,u2:3,u7:5},rAdv:{u4:3,u7:5},body:`Ik splits de verbouwingskosten in een deel gewone verbouwing en een deel energiebesparende maatregelen, met een specificatie van de aannemer erbij. Dan kun je in de toets laten zien waar extra leenruimte op gebaseerd is volgens de actuele normen. Leg de offerte en het energielabel vast in het dossier.`},
   {id:'vbl-014-a2',auteur:'u5',datum:'2025-11-18T07:04:00',rA:{u3:5,u2:3},rAdv:{},body:`Let op dat de geldverstrekker vaak een bouwkundig rapport of specificatie wil zien en dat het bedrag in een bouwdepot komt. Check de voorwaarden van de geldverstrekker en de actuele leennormen voor verduurzaming.`},
   {id:'vbl-014-a3',auteur:'u6',datum:'2025-11-18T12:37:00',rA:{u4:3,u5:5},rAdv:{u4:3},body:`In eBlinqx neem je de verbouwing en het energiebespaarbudget op in de financieringsopzet; het kennisbankartikel over de financieringsopzet heeft daar een paragraaf over. Controleer daarna in het rapport of de bedragen apart te herkennen zijn.`}
  ]},
 {id:'vbl-015',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T11:55:00',views:258,tags:['fastlane','eblinqx','naamgeving'],beste:'vbl-015-a1',
  titel:'Is Fastlane hetzelfde als eBlinqx Hypotheekadvies?',
  body:`Een nieuwe collega vraagt of hij Fastlane of eBlinqx Hypotheekadvies moet gebruiken. In supportartikelen kom ik beide namen tegen. Is dat hetzelfde pakket?`,
  antwoorden:[
   {id:'vbl-015-a1',auteur:'u6',datum:'2025-11-21T13:59:00',rA:{u7:5},rAdv:{},body:`Ja, eBlinqx Hypotheekadvies en Fastlane (Fastlane Advies) zijn hetzelfde pakket; supportartikelen gebruiken beide namen. Adviesbox Online is wel een ander adviespakket, dat je via een koppeling met eBlinqx gebruikt. Leg dat in je werkinstructie vast, dan voorkom je verwarring bij nieuwe collega's.`}
  ]},
 {id:'vbl-016',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-24T15:25:00',views:356,tags:['rapport','huisstijl','pdf'],beste:'vbl-016-a1',
  titel:'Logo en huisstijl in het adviesrapport',
  body:`Wij willen dat het adviesrapport uit eBlinqx Hypotheekadvies in onze huisstijl komt, met logo. Ik vind de instelling niet. Bestaat die?`,
  antwoorden:[
   {id:'vbl-016-a1',auteur:'u6',datum:'2025-11-25T13:48:00',rA:{u7:5,u8:3},rAdv:{u8:3},body:`Op dit moment niet: rapporten zijn altijd PDF met standaardopmaak, en huisstijl, logo of kleuren zijn niet zelf aan te passen. Dat los je ook niet op via het portaalprofiel. Wil je toch een eigen voorblad, dan kun je dat als apart document meesturen.`},
   {id:'vbl-016-a2',auteur:'u8',datum:'2025-11-26T03:56:00',rA:{u2:5},rAdv:{},body:`Als je een eigen voorblad of begeleidende brief toevoegt, zorg dan dat de inhoud niet afwijkt van het rapport. Bewaar het totaalpakket zoals de klant het heeft ontvangen in het dossier.`}
  ]},
 {id:'vbl-017',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-28T17:05:00',views:582,tags:['pdf','rapport','berekeningen vergelijken'],beste:'vbl-017-a1',
  titel:'Waar maak ik de PDF van de berekening?',
  body:`Ik wil de klant een PDF sturen van de berekening met twee varianten. Ik zie geen knop voor afdrukken. Waar zit die?`,
  antwoorden:[
   {id:'vbl-017-a1',auteur:'u6',datum:'2025-11-29T05:27:00',rA:{u2:5,u5:4},rAdv:{u5:4},body:`Open de berekening, klik rechtsboven op "Berekeningen vergelijken" en daarna op het PDF-icoon. Zo komen beide varianten in de PDF. Sla de PDF die de klant krijgt op in het dossier, met datum.`},
   {id:'vbl-017-a2',auteur:'u1',datum:'2025-11-29T09:39:00',rA:{u3:4,u2:5,u6:3,u8:4},rAdv:{u2:5,u6:3},body:`Tip: geef je varianten vooraf een duidelijke naam, bijvoorbeeld met de rentevaste periode erin. Dat leest voor de klant veel prettiger dan Berekening 1 en 2.`}
  ]},
 {id:'vbl-018',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-02T16:45:00',views:14,tags:['starterslening','financieringsopzet','toetsing'],beste:null,
  titel:'Starterslening opnemen in de financieringsopzet',
  body:`Mijn klant maakt gebruik van een starterslening van de gemeente. Hoe neem ik die op in eBlinqx zodat de toets en de opzet kloppen?`,
  antwoorden:[
   {id:'vbl-018-a1',auteur:'u6',datum:'2025-12-03T14:07:00',rA:{u1:4,u5:4,u8:4},rAdv:{u1:4,u5:4},body:`De starterslening komt in de financieringsopzet als aparte financieringsbron; het kennisbankartikel over de financieringsopzet heeft er een eigen paragraaf over. Controleer daarna in de toets of de last op de juiste manier wordt meegenomen.`},
   {id:'vbl-018-a2',auteur:'u4',datum:'2025-12-03T23:48:00',rA:{u8:3,u2:4,u5:4,u6:4},rAdv:{u2:4},body:`Controleer de voorwaarden van de gemeente en van de geldverstrekker: hoe de starterslening in de toets wordt meegenomen verschilt. Vraag de toewijzing tijdig aan, de doorlooptijd kan lang zijn. Leg de toewijzingsbrief vast in het dossier.`}
  ]},
 {id:'vbl-019',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-05T13:00:00',views:375,tags:['leningdelen','hoofdsom','melding'],beste:'vbl-019-a1',
  titel:'Optelsom leningdelen sluit niet aan op hoofdsom',
  body:`Ik krijg steeds de melding dat er een extra leningdeel nodig is. Ik heb drie leningdelen ingevuld en wil er geen vierde bij. Wat gaat er mis?`,
  antwoorden:[
   {id:'vbl-019-a1',auteur:'u6',datum:'2025-12-05T14:10:00',rA:{u3:4,u8:4},rAdv:{},body:`Is de optelsom van de leningdelen niet gelijk aan de hoofdsom, dan vraagt eBlinqx automatisch om een extra leningdeel. Tel de drie delen na en vergelijk met de hoofdsom; vaak zit er een klein verschil in. Pas het kleinste leningdeel aan, dan verdwijnt de melding.`}
  ]},
 {id:'vbl-020',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-09T10:40:00',views:325,tags:['overbrugging','verkoop','overwaarde'],beste:'vbl-020-a1',
  titel:'Overbrugging bij een al verkochte woning',
  body:`De huidige woning is verkocht en de ontbindende voorwaarden zijn verlopen. In eBlinqx rekent de overbrugging met een lager bedrag dan de verkoopprijs. Hoe pas ik dat aan?`,
  antwoorden:[
   {id:'vbl-020-a1',auteur:'u6',datum:'2025-12-10T03:10:00',rA:{u8:5,u3:5,u4:5,u5:4},rAdv:{u8:5,u3:5,u4:5,u5:4},body:`Standaard rekent eBlinqx met 90% van de verwachte verkoopprijs minus de resterende hypotheekschuld. Bij een onvoorwaardelijk verkochte woning kan in sommige gevallen 100% van de overwaarde meetellen; dat pas je aan via het overbruggingspercentage onder Eigen geld. Controleer de voorwaarden van de geldverstrekker voordat je dat doet.`},
   {id:'vbl-020-a2',auteur:'u5',datum:'2025-12-10T14:31:00',rA:{u3:3},rAdv:{},body:`Leg de definitieve koopovereenkomst en het bewijs dat de ontbindende voorwaarden zijn verlopen vast in het dossier. Houd ook rekening met verkoopkosten en een eventuele boeterente op de oude hypotheek.`},
   {id:'vbl-020-a3',auteur:'u1',datum:'2025-12-10T20:09:00',rA:{},rAdv:{},body:`Ik zou nog steeds een scenario doorrekenen voor het geval de levering vertraagt. Dat hoort bij een zorgvuldige analyse van de dubbele lasten.`}
  ]},
 {id:'vbl-021',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-13T15:40:00',views:165,tags:['oversluiten','boeterente','fiscaal'],beste:null,
  titel:'Boeterente bij oversluiten opnemen',
  body:`Bij een oversluiting wil ik de boeterente meefinancieren. Waar voer ik die in? En hoe zit het met de aftrekbaarheid in de berekening?`,
  antwoorden:[
   {id:'vbl-021-a1',auteur:'u6',datum:'2025-12-13T19:49:00',rA:{u3:3,u1:5,u8:4},rAdv:{u3:3},body:`De boeterente is een vast veld in de financieringsopzet dat je kunt invullen of wijzigen. Oversluitkosten die geen vast veld hebben voeg je toe via "Voeg extra veld toe". Let op dat handmatige posten niet automatisch in de belastingcomponenten meetellen.`},
   {id:'vbl-021-a2',auteur:'u5',datum:'2025-12-14T01:34:00',rA:{u4:5,u3:4,u7:3,u1:5},rAdv:{u3:4,u7:3,u1:5},body:`Vraag een actuele opgave van de boeterente op bij de huidige geldverstrekker en leg die vast. Maak een terugverdienberekening: wanneer is oversluiten voordeliger dan blijven zitten? Toets de fiscale behandeling aan de actuele regels.`},
   {id:'vbl-021-a3',auteur:'u2',datum:'2025-12-14T05:20:00',rA:{u1:5,u5:4},rAdv:{u1:5,u5:4},body:`De AFM verwacht bij oversluiten dat je de terugverdientijd en de alternatieven, zoals rentemiddeling, onderbouwt. Neem dat op in het adviesrapport.`}
  ]},
 {id:'vbl-022',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-16T09:25:00',views:101,tags:['nhg','borgtochtprovisie','financieringsopzet'],beste:null,
  titel:'NHG-borgtochtprovisie handmatig aanpassen',
  body:`De borgtochtprovisie in mijn opzet lijkt niet te kloppen met wat ik verwacht. Ik zie geen veld om hem aan te passen. Hoe doen jullie dat?`,
  antwoorden:[
   {id:'vbl-022-a1',auteur:'u6',datum:'2025-12-16T12:16:00',rA:{u3:3,u4:4},rAdv:{u3:3,u4:4},body:`De NHG-borgtochtprovisie pas je niet handmatig aan; die volgt uit de NHG-keuze per leningdeel. Controleer per leningdeel of NHG aan of uit staat. Klopt het daarna nog niet, stuur dan de berekening naar support met een omschrijving van wat je verwacht.`}
  ]},
 {id:'vbl-023',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-20T16:25:00',views:133,tags:['handmatige invoer','netto maandlast','fiscaal'],beste:'vbl-023-a1',
  titel:'Handmatige kostenposten en fiscale berekening',
  body:`Ik heb een paar kosten handmatig toegevoegd. De netto maandlast verandert niet. Is dat de bedoeling?`,
  antwoorden:[
   {id:'vbl-023-a1',auteur:'u6',datum:'2025-12-21T09:43:00',rA:{u3:4,u7:4,u2:5,u5:3},rAdv:{u3:4,u7:4},body:`Ja: handmatige posten tellen mee in het totaal, maar niet in de belastingcomponenten. Zodra je handmatig invoert, vervalt op dat punt de automatische fiscale berekening. Gebruik waar mogelijk de vaste velden en leg handmatige invoer en de onderbouwing vast in de motivatie.`},
   {id:'vbl-023-a2',auteur:'u5',datum:'2025-12-21T13:36:00',rA:{},rAdv:{},body:`Gaat het om kosten die je fiscaal wilt meenemen, beoordeel dat dan zelf aan de hand van de actuele regels. Maak een korte notitie in het dossier waarom iets wel of niet aftrekbaar is.`}
  ]},
 {id:'vbl-024',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-24T11:10:00',views:328,tags:['scenario','rentevaste periode','rapport'],beste:null,
  titel:'Meerdere scenarios aan de klant presenteren',
  body:`Ik werk vaak met drie varianten: lange rentevaste periode, korte periode en een mix. Hoe laten jullie dat in het rapport zien zonder dat de klant het overzicht kwijtraakt?`,
  antwoorden:[
   {id:'vbl-024-a1',auteur:'u1',datum:'2025-12-24T13:12:00',rA:{u4:5},rAdv:{u4:5},body:`Ik gebruik Berekeningen vergelijken en neem maximaal drie varianten op. Elke variant krijgt een naam die zegt wat hij is. In het rapport licht ik mijn advies toe en waarom de andere varianten minder passend zijn.`},
   {id:'vbl-024-a2',auteur:'u4',datum:'2025-12-24T17:56:00',rA:{},rAdv:{},body:`Ik leg vast welke variant de klant kiest en waarom, ook als hij afwijkt van mijn advies. Dat is precies wat de AFM bij een dossiercheck wil terugzien.`},
   {id:'vbl-024-a3',auteur:'u6',datum:'2025-12-24T23:48:00',rA:{u1:4,u5:4,u8:5,u7:5},rAdv:{},body:`Technisch: de rentevaste periode zit op het leningdeel, niet op het scenario. Bij een mix voeg je dus binnen één berekening meerdere leningdelen toe met elk een eigen periode.`}
  ]},
 {id:'vbl-025',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-27T10:45:00',views:477,tags:['taxatie','kostenpost','extra veld'],beste:'vbl-025-a1',
  titel:'Taxatiekosten opnemen als kostenpost',
  body:`De taxatiekosten staan niet als vast veld in mijn financieringsopzet. Kan ik ze toch opnemen?`,
  antwoorden:[
   {id:'vbl-025-a1',auteur:'u6',datum:'2025-12-27T20:28:00',rA:{u8:5,u7:4},rAdv:{},body:`Ja, via "Voeg extra veld toe" onder Kosten van de woning kun je eigen kostenposten opnemen, bijvoorbeeld taxatiekosten. Omschrijf de post duidelijk, zodat hij in het rapport herkenbaar is.`},
   {id:'vbl-025-a2',auteur:'u1',datum:'2025-12-28T05:30:00',rA:{u2:3},rAdv:{u2:3},body:`Ik neem het bedrag over uit de opdrachtbevestiging van de taxateur en sla die op in het dossier. Kosten die de klant al zelf heeft betaald, laat ik als eigen inbreng zien.`}
  ]},
 {id:'vbl-026',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-30T08:35:00',views:247,tags:['HDN','aanvraag','validatie'],beste:'vbl-026-a1',
  titel:'HDN-aanvraag geeft validatiefout bij versturen',
  body:`Ik wil een aanvraag via HDN versturen vanuit eBlinqx Hypotheekadvies, maar krijg een validatiefout. De melding noemt een veld dat volgens mij gewoon is ingevuld. Hoe vinden jullie snel waar het probleem zit?`,
  antwoorden:[
   {id:'vbl-026-a1',auteur:'u6',datum:'2025-12-31T13:35:00',rA:{},rAdv:{},body:`Een validatiefout betekent dat het bericht niet voldoet aan de eisen van het HDN-berichtformaat of van de ontvangende partij. Open het meldingenoverzicht en klik door naar het genoemde veld; vaak zit het probleem bij een tweede aanvrager of een tweede leningdeel waar hetzelfde veld leeg is. Let ook op velden die wel gevuld zijn maar een ongeldig formaat hebben, zoals een postcode met spatie of een datum in de toekomst. Verstuur pas opnieuw als het overzicht geen fouten meer toont.`},
   {id:'vbl-026-a2',auteur:'u4',datum:'2026-01-01T20:37:00',rA:{u8:5},rAdv:{u8:5},body:`Bij mij zat het een keer in de gegevens van het legitimatiebewijs van de partner: de geldigheidsdatum was verlopen. Ik loop nu voor elke aanvraag de persoonsgegevens van beide aanvragers na voordat ik verstuur. Dat scheelt een hoop heen en weer.`}
  ]},
 {id:'vbl-027',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-03T08:05:00',views:531,tags:['HDN','statusbericht','aanvraag'],beste:null,
  titel:'Statusbericht van de geldverstrekker komt niet binnen',
  body:`Ik heb een week geleden een aanvraag via HDN verstuurd, maar ik zie geen enkel statusbericht terug in het dossier. De geldverstrekker zegt dat de aanvraag in behandeling is. Waar kan het aan liggen?`,
  antwoorden:[
   {id:'vbl-027-a1',auteur:'u6',datum:'2026-01-04T22:55:00',rA:{u1:3},rAdv:{u1:3},body:`Controleer eerst of de aanvraag echt als verzonden staat en of er een ontvangstbevestiging is. Statusberichten worden gekoppeld op basis van het aanvraagnummer; als de aanvraag opnieuw is ingediend of handmatig is aangemaakt bij de geldverstrekker, kan de koppeling ontbreken. Kijk ook in de algemene berichtenbox of het bericht daar zonder dossierkoppeling staat. Blijft het leeg, meld het dan bij de support met het aanvraagnummer en de verzenddatum.`},
   {id:'vbl-027-a2',auteur:'u1',datum:'2026-01-05T00:07:00',rA:{u4:5,u8:4},rAdv:{u4:5,u8:4},body:`Praktische tip: noteer in het dossier wanneer je telefonisch een status hebt gekregen en van wie. Dan kun je de klant toch informeren en is het later terug te vinden als het bericht alsnog binnenkomt.`}
  ]},
 {id:'vbl-028',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-06T15:45:00',views:155,tags:['HDN','offerte','koppeling'],beste:'vbl-028-a1',
  titel:'Offerte via HDN ontvangen maar niet gekoppeld aan het dossier',
  body:`De offerte is binnengekomen via HDN, maar staat niet bij het juiste dossier. Ik zie hem alleen in een algemeen overzicht van ontvangen berichten. Kan ik hem alsnog handmatig koppelen?`,
  antwoorden:[
   {id:'vbl-028-a1',auteur:'u6',datum:'2026-01-07T10:36:00',rA:{u2:5},rAdv:{},body:`In de meeste gevallen kun je een ongekoppeld bericht vanuit het berichtenoverzicht alsnog aan een dossier hangen. Controleer daarbij goed of naam, geboortedatum en aanvraagnummer overeenkomen, zodat je de offerte niet aan de verkeerde klant koppelt. Ontstaat dit vaker, kijk dan of je dossiers dubbel hebt aangemaakt; dat is een bekende oorzaak.`},
   {id:'vbl-028-a2',auteur:'u8',datum:'2026-01-07T17:03:00',rA:{u2:4},rAdv:{u2:4},body:`Let er bij het handmatig koppelen op dat je persoonsgegevens niet in een ander dossier terechtkomen. Een verkeerd gekoppelde offerte is een datalek-risico. Laat bij twijfel een collega meekijken en leg vast wie de koppeling heeft gemaakt.`}
  ]},
 {id:'vbl-029',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-10T17:20:00',views:117,tags:['HDN','aanvraag','dossier'],beste:'vbl-029-a1',
  titel:'Tweede aanvraag bij een andere geldverstrekker vanuit hetzelfde dossier',
  body:`De eerste geldverstrekker heeft afgewezen en ik wil vanuit hetzelfde dossier een aanvraag bij een andere geldverstrekker doen. Moet ik een nieuw dossier aanmaken of kan ik de bestaande aanvraag kopiëren? Ik wil de historie van de afwijzing graag bewaren.`,
  antwoorden:[
   {id:'vbl-029-a1',auteur:'u6',datum:'2026-01-11T06:10:00',rA:{u4:3,u8:3},rAdv:{u4:3,u8:3},body:`Je hoeft geen nieuw dossier aan te maken. Maak binnen het dossier een nieuwe berichtvariant of kopie van de aanvraag aan en kies daar de andere geldverstrekker. De oorspronkelijke aanvraag en de berichten blijven dan bewaard. Controleer na het kopiëren wel de productkeuze, rentevaste periode en voorwaarden, want die verschillen per geldverstrekker.`},
   {id:'vbl-029-a2',auteur:'u5',datum:'2026-01-12T09:44:00',rA:{u8:4},rAdv:{u8:4},body:`Leg in het dossier vast waarom de eerste aanvraag is afgewezen en waarom de nieuwe geldverstrekker wel passend is. Bespreek ook met de klant of de afwijzing iets zegt over de haalbaarheid, bijvoorbeeld bij inkomen of BKR. Dat is belangrijk voor je motivatie.`},
   {id:'vbl-029-a3',auteur:'u4',datum:'2026-01-12T17:33:00',rA:{u3:4,u6:5,u7:4,u5:4},rAdv:{u3:4,u6:5,u5:4},body:`Vergeet niet de klant opnieuw toestemming te vragen voor het delen van gegevens met de nieuwe partij als dat in jullie werkwijze zo is ingericht.`}
  ]},
 {id:'vbl-030',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-13T08:30:00',views:592,tags:['Adviesbox','HBX','import'],beste:null,
  titel:'Wat is een HBX-bestand in Adviesbox Online?',
  body:`Een collega van een ander kantoor stuurt mij een HBX-bestand van een klant die naar ons overstapt. Ik werk zelf met Adviesbox Online. Wat kan ik met zo een bestand en waar moet ik op letten?`,
  antwoorden:[
   {id:'vbl-030-a1',auteur:'u6',datum:'2026-01-13T13:36:00',rA:{u3:3},rAdv:{u3:3},body:`HBX is een uitwisselformaat waarmee dossiergegevens tussen adviespakketten kunnen worden overgezet. Of en hoe je het kunt importeren hangt af van de inrichting van jullie omgeving; kijk in de handleiding of vraag het na bij de support van het pakket. Controleer na een import altijd alle gegevens tegen de brondocumenten, vooral inkomen, lopende leningen en verplichtingen.`},
   {id:'vbl-030-a2',auteur:'u8',datum:'2026-01-15T00:59:00',rA:{u1:5},rAdv:{u1:5},body:`Belangrijker nog: zorg dat de klant toestemming heeft gegeven om zijn gegevens van het andere kantoor naar jullie over te dragen. Verstuur zo een bestand niet via gewone e-mail maar via een beveiligde weg. Leg vast wanneer en van wie je het bestand hebt ontvangen.`}
  ]},
 {id:'vbl-031',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-17T17:40:00',views:52,tags:['Adviesbox','GUID','koppeling'],beste:'vbl-031-a1',
  titel:'GUID in Adviesbox Online: waar heb ik die voor nodig?',
  body:`In de instellingen van een koppeling wordt gevraagd om een GUID. Ik weet niet goed wat dat is en waar ik die vind. Kan iemand dat in gewone taal uitleggen?`,
  antwoorden:[
   {id:'vbl-031-a1',auteur:'u6',datum:'2026-01-18T10:00:00',rA:{u2:4,u7:3,u1:5},rAdv:{u2:4,u1:5},body:`Een GUID is een unieke code die een record identificeert, bijvoorbeeld een dossier, relatie of omgeving. Koppelingen gebruiken die code om zeker te weten dat ze het juiste record bijwerken. Waar je hem vindt, verschilt per scherm; meestal staat hij bij de technische gegevens of instellingen. Kopieer de code altijd volledig en typ hem niet over.`},
   {id:'vbl-031-a2',auteur:'u2',datum:'2026-01-20T10:46:00',rA:{},rAdv:{},body:`Bij ons ging het mis omdat iemand een GUID uit een testomgeving had gebruikt. Controleer dus ook of je in de productieomgeving zit voordat je hem invult.`}
  ]},
 {id:'vbl-032',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-21T14:50:00',views:119,tags:['CRM','koppeling','dubbele relaties'],beste:'vbl-032-a1',
  titel:'Dubbele relaties na koppeling tussen adviespakket en CRM',
  body:`Sinds we de koppeling tussen ons adviespakket en het CRM gebruiken, zie ik klanten dubbel in het CRM. Eén record komt uit de koppeling en één had ik zelf al aangemaakt. Hoe voorkomen jullie dit?`,
  antwoorden:[
   {id:'vbl-032-a1',auteur:'u6',datum:'2026-01-22T11:34:00',rA:{u7:5,u2:3},rAdv:{u2:3},body:`Dit gebeurt meestal wanneer de unieke sleutel van de relatie, zoals een GUID, in beide systemen niet overeenkomt. De koppeling herkent het bestaande record dan niet en maakt een nieuw aan. Spreek af welk systeem leidend is voor het aanmaken van relaties en start nieuwe klanten alleen daar. Bestaande dubbelen voeg je samen, en controleer daarna of documenten en notities bij het juiste record staan.`},
   {id:'vbl-032-a2',auteur:'u8',datum:'2026-01-22T20:59:00',rA:{u7:5,u1:5},rAdv:{u7:5,u1:5},body:`Bij het samenvoegen van dubbele records moet je oppassen dat er geen gegevens verloren gaan die je wettelijk moet bewaren. Exporteer zo nodig eerst de historie. Leg ook vast welke records zijn samengevoegd.`}
  ]},
 {id:'vbl-033',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-24T11:55:00',views:78,tags:['inkomen','UWV','invoer'],beste:null,
  titel:'Inkomensgegevens uit UWV-verzekeringsbericht overnemen',
  body:`Mijn klant heeft een UWV-verzekeringsbericht aangeleverd. Kan ik die gegevens ergens automatisch inlezen, of moet ik alles handmatig overtypen in het adviespakket?`,
  antwoorden:[
   {id:'vbl-033-a1',auteur:'u6',datum:'2026-01-25T21:55:00',rA:{u4:5,u5:5,u3:5},rAdv:{u4:5,u5:5,u3:5},body:`Het verzekeringsbericht als losse PDF lees je voor zover bekend niet automatisch in. De route om UWV-gegevens automatisch binnen te krijgen is de Ockto-koppeling. De klant haalt dan met DigiD zijn gegevens op bij onder andere UWV, Belastingdienst en Mijnpensioenoverzicht, en geeft toestemming om ze te delen.
- Het Ockto-bericht wordt automatisch aan het dossier gekoppeld en staat in het dossier onder Home, Brondata.
- Vanuit daar gebruik je de gegevens in het adviestraject, zodat je minder hoeft over te typen.
- Op de supportsite staat een artikel over het instellen en gebruiken van de Ockto-koppeling; daar heb je mogelijk beheerrechten voor nodig. Werkt de koppeling niet, mail dan support-eblinqx@blinqx.tech.
Controleer ingelezen gegevens altijd tegen de brondocumenten, zeker inkomensbestanddelen zoals onregelmatigheidstoeslag of een vaste eindejaarsuitkering. Leg vast welke bron je hebt gebruikt.`}
  ]},
 {id:'vbl-034',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-28T08:50:00',views:581,tags:['offerte','ondertekenen','HDN'],beste:null,
  titel:'Klant wil de offerte digitaal ondertekenen',
  body:`De geldverstrekker biedt de mogelijkheid om de offerte digitaal te laten ondertekenen. Zie ik in het adviespakket terug wanneer de klant heeft getekend? Of moet ik dat bij de geldverstrekker zelf controleren?`,
  antwoorden:[
   {id:'vbl-034-a1',auteur:'u1',datum:'2026-01-28T13:36:00',rA:{u2:5},rAdv:{u2:5},body:`Dat hangt af van de geldverstrekker en welke statusberichten die via HDN terugstuurt. Bij sommige zie je een status dat de getekende offerte is ontvangen, bij andere niet. Ik controleer het daarom altijd ook in het portaal van de geldverstrekker. Noteer de datum van ondertekening in het dossier, want die is relevant voor termijnen in de offerte.`},
   {id:'vbl-034-a2',auteur:'u6',datum:'2026-01-30T10:35:00',rA:{},rAdv:{},body:`Je kunt in het dossier een taak aanmaken met een herinnering op de uiterste tekendatum. Dan zie je snel welke offertes nog openstaan.`}
  ]},
 {id:'vbl-035',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-01T15:10:00',views:383,tags:['HDN','status','intrekken'],beste:'vbl-035-a1',
  titel:'Aanvraag ingetrokken maar status blijft in behandeling',
  body:`Ik heb een aanvraag ingetrokken bij de geldverstrekker, maar in het dossier blijft de status in behandeling staan. Hierdoor klopt mijn pijplijnoverzicht niet meer. Kan ik de status zelf aanpassen?`,
  antwoorden:[
   {id:'vbl-035-a1',auteur:'u6',datum:'2026-02-02T10:09:00',rA:{u8:4,u2:5},rAdv:{u2:5},body:`Als de geldverstrekker geen intrekkingsbericht terugstuurt, blijft de status staan zoals hij was. Je kunt de aanvraag in het dossier meestal handmatig afsluiten of als vervallen markeren. Zet er een notitie bij met de datum en de reden van intrekking. Dan klopt je overzicht weer en is het later uit te leggen.`}
  ]},
 {id:'vbl-036',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-04T14:55:00',views:376,tags:['HDN','bijlagen','documenten'],beste:null,
  titel:'Bijlagen meesturen met een HDN-aanvraag',
  body:`Kan ik documenten zoals werkgeversverklaring en salarisstroken direct meesturen met de HDN-aanvraag? Of moet ik ze apart uploaden bij de geldverstrekker? Ik wil voorkomen dat stukken dubbel binnenkomen.`,
  antwoorden:[
   {id:'vbl-036-a1',auteur:'u4',datum:'2026-02-04T18:45:00',rA:{u1:5,u8:4},rAdv:{u1:5},body:`Dat verschilt per geldverstrekker. Sommige verwachten de stukken via hun eigen portaal of een documentenservice, andere accepteren documenten via de HDN-route. Ik check de instructies van de geldverstrekker voordat ik de stukken verstuur en noteer in het dossier welke stukken wanneer en via welke route zijn aangeleverd.`},
   {id:'vbl-036-a2',auteur:'u6',datum:'2026-02-04T23:53:00',rA:{u3:5,u5:3,u8:5},rAdv:{u3:5,u5:3,u8:5},body:`In het dossier kun je per document een status bijhouden, bijvoorbeeld opgevraagd, ontvangen en doorgestuurd. Dat maakt het overzicht voor jou en je backoffice een stuk eenvoudiger.`}
  ]},
 {id:'vbl-037',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-08T09:35:00',views:133,tags:['rente','offerte','berekening'],beste:'vbl-037-a1',
  titel:'Rente in de berekening wijkt af van de rente in de offerte',
  body:`In mijn berekening heb ik een rente gebruikt, maar de offerte komt terug met een andere rente. Moet ik de berekening en het rapport dan aanpassen? Wat leggen jullie vast?`,
  antwoorden:[
   {id:'vbl-037-a1',auteur:'u5',datum:'2026-02-08T15:25:00',rA:{u4:3,u6:5},rAdv:{u6:5},body:`Ja, ik werk de berekening bij met de rente uit de offerte en controleer of de maandlasten en de toetsing nog passen binnen de actuele leennormen. Is het verschil groot, dan bespreek ik het met de klant voordat hij tekent. In het dossier leg ik vast welke rente ik eerst heb gehanteerd, wat de offerte zegt en dat ik de klant heb geïnformeerd.`},
   {id:'vbl-037-a2',auteur:'u1',datum:'2026-02-11T08:54:00',rA:{u7:4,u5:3,u8:3},rAdv:{u7:4,u5:3},body:`Controleer ook of het verschil komt door een andere rentevaste periode, een andere risicoklasse of een andere ingangsdatum. Soms zit de fout in de invoer en niet in de offerte.`}
  ]},
 {id:'vbl-038',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-12T09:05:00',views:471,tags:['rapport','ondertekenen','aanvragers'],beste:null,
  titel:'Rapportage met twee aanvragers die apart willen tekenen',
  body:`Mijn klanten wonen niet samen en willen elk een eigen exemplaar van het adviesrapport ondertekenen. Kan ik het rapport per aanvrager laten aanmaken? Of is één rapport met twee handtekeningen gebruikelijk?`,
  antwoorden:[
   {id:'vbl-038-a1',auteur:'u5',datum:'2026-02-14T20:39:00',rA:{},rAdv:{},body:`Bij een gezamenlijke hypotheek is één rapport met beide namen en twee handtekeningen gebruikelijk, omdat het advies over de gezamenlijke financiering gaat. Elke aanvrager krijgt dan een kopie. Willen ze afzonderlijke ondertekening, dan kun je het rapport twee keer laten ondertekenen, maar de inhoud moet gelijk zijn. Leg vast dat beide aanvragers het rapport hebben ontvangen.`}
  ]},
 {id:'vbl-039',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-15T10:15:00',views:254,tags:['woonlastenbeschermer','rapport','risico'],beste:'vbl-039-a1',
  titel:'Woonlastenbeschermer in het adviesrapport opnemen',
  body:`Ik adviseer naast de hypotheek een woonlastenbeschermer. Waar zet ik dat in het adviesrapport, zodat het verband met het risico op arbeidsongeschiktheid en werkloosheid duidelijk is?`,
  antwoorden:[
   {id:'vbl-039-a1',auteur:'u3',datum:'2026-02-15T14:47:00',rA:{u2:5},rAdv:{},body:`Ik neem het op in het hoofdstuk over risico’s, direct na de analyse van arbeidsongeschiktheid en werkloosheid. Eerst laat je het tekort zien, daarna de oplossing en wat die dekt. Noem ook duidelijk de beperkingen, zoals wachttijden, uitkeringsduur en uitsluitingen, en verwijs naar de polisvoorwaarden van de verzekeraar.`},
   {id:'vbl-039-a2',auteur:'u8',datum:'2026-02-16T22:42:00',rA:{},rAdv:{},body:`Leg ook vast als de klant de woonlastenbeschermer niet wil. Een expliciete keuze van de klant om een risico te accepteren hoort in het dossier, inclusief de toelichting die je hebt gegeven.`},
   {id:'vbl-039-a3',auteur:'u6',datum:'2026-02-17T15:52:00',rA:{u7:4,u3:3},rAdv:{u7:4},body:`Technisch: als je het product in het adviespakket opneemt bij de risicoberekening, komt het meestal automatisch op de juiste plek in het rapport. Controleer na het genereren of de tekst klopt.`}
  ]},
 {id:'vbl-040',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-19T12:10:00',views:509,tags:['HDN','aanvraag','correctie'],beste:null,
  titel:'Fout in een al verstuurde aanvraag herstellen',
  body:`Ik ontdek dat ik in een verstuurde aanvraag een verkeerd brutojaarinkomen heb gezet. Kan ik een correctie sturen of moet ik de aanvraag intrekken en opnieuw indienen?`,
  antwoorden:[
   {id:'vbl-040-a1',auteur:'u4',datum:'2026-02-19T17:30:00',rA:{u7:4,u8:4},rAdv:{u8:4},body:`Bel eerst de acceptant om te vragen hoe zij een correctie willen ontvangen. Sommige geldverstrekkers accepteren een nagekomen correctie, andere vragen om een nieuwe aanvraag. Pas in elk geval de gegevens in het dossier aan, zodat berekening en rapport kloppen. Leg vast wat er fout was, wanneer je het hebt gecorrigeerd en hoe.`},
   {id:'vbl-040-a2',auteur:'u6',datum:'2026-02-20T22:39:00',rA:{u8:3,u1:4,u5:5,u2:5},rAdv:{u1:4,u2:5},body:`Een al verstuurd bericht kun je niet aanpassen; een nieuw bericht maak je vanuit de gecorrigeerde gegevens. Let op dat je niet per ongeluk twee lopende aanvragen bij dezelfde geldverstrekker hebt.`}
  ]},
 {id:'vbl-041',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-23T15:10:00',views:430,tags:['maximale hypotheek','toetsing','berekening'],beste:'vbl-041-a1',
  titel:'Berekening toont ander maximaal hypotheekbedrag dan de geldverstrekker',
  body:`Volgens mijn berekening in het adviespakket kan de klant meer lenen dan de geldverstrekker uiteindelijk accepteert. Waar komt dat verschil meestal door? Ik wil dit vooraf beter inschatten.`,
  antwoorden:[
   {id:'vbl-041-a1',auteur:'u5',datum:'2026-02-24T23:40:00',rA:{u4:5},rAdv:{},body:`Het adviespakket rekent met de wettelijke leennormen. Geldverstrekkers kunnen strenger zijn in hun eigen acceptatiebeleid, bijvoorbeeld bij flexibel inkomen, zelfstandigen of bepaalde verplichtingen. Controleer daarom altijd de acceptatievoorwaarden van de geldverstrekker. Ik leg in het dossier vast welke berekening ik gebruikt heb en welke voorwaarden ik heb gecontroleerd.`},
   {id:'vbl-041-a2',auteur:'u1',datum:'2026-02-25T13:31:00',rA:{u6:5,u4:5},rAdv:{u6:5,u4:5},body:`Kijk ook naar de toetsrente en de looptijd van de leningdelen. Een kleine afwijking in de invoer, zoals een verkeerde rentevaste periode, kan al een verschil geven.`}
  ]},
 {id:'vbl-042',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-26T11:10:00',views:86,tags:['archief','PDF','dossier'],beste:null,
  titel:'Exporteren van een dossier naar PDF voor het archief',
  body:`Wij willen dossiers na afronding als PDF archiveren buiten het adviespakket. Kan ik het hele dossier inclusief notities in één keer exporteren?`,
  antwoorden:[
   {id:'vbl-042-a1',auteur:'u6',datum:'2026-02-28T00:10:00',rA:{u1:4,u2:4,u5:5},rAdv:{u1:4,u2:4,u5:5},body:`Een knop om het hele dossier inclusief notities in één keer als PDF te exporteren ken ik niet. Wel zijn er onderdelen die je kunt gebruiken:
- Brieven en formulieren in het dossier zet je om naar PDF; die komen in de tab Documenten.
- In het klantdossier kun je een samenvatting afdrukken, die volgens de AVG-veelgestelde vragen ook bedoeld is voor inzageverzoeken.
- Volgens dezelfde informatie kunnen alle klantgegevens worden geëxporteerd.
Vraag bij de eBlinqx-support (support-eblinqx@blinqx.tech) na wat in jullie omgeving mogelijk is voor archivering. Leg daarnaast in je beleid vast welke onderdelen het archief moet bevatten, zoals het adviesrapport, de inventarisatie, de berekeningen, de correspondentie en de notities, en hoe lang je ze bewaart. Controleer na de export steeds of alles compleet is.`}
  ]},
 {id:'vbl-043',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-02T17:25:00',views:79,tags:['machtiging','toestemming','dossier'],beste:'vbl-043-a1',
  titel:'Machtiging voor het opvragen van gegevens vastleggen',
  body:`Ik vraag met toestemming van de klant gegevens op bij externe bronnen. Waar leggen jullie die toestemming vast in het adviespakket of het CRM?`,
  antwoorden:[
   {id:'vbl-043-a1',auteur:'u8',datum:'2026-03-03T14:04:00',rA:{u3:5,u6:5,u1:5,u4:3},rAdv:{u3:5,u6:5},body:`Leg de toestemming vast bij de relatie in het CRM met datum, doel en de bron waarvoor de toestemming geldt. Bewaar het getekende document of de digitale bevestiging als bijlage. Zo kun je bij een controle aantonen dat je de gegevens rechtmatig hebt opgevraagd.`},
   {id:'vbl-043-a2',auteur:'u6',datum:'2026-03-04T09:28:00',rA:{u4:3,u2:3,u1:5},rAdv:{u4:3,u2:3},body:`Sommige omgevingen hebben een apart documenttype voor machtigingen. Gebruik dat als het er is, dan kun je er later ook op filteren.`}
  ]},
 {id:'vbl-044',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-06T11:25:00',views:458,tags:['rentevoorstel','termijnen','taken'],beste:null,
  titel:'Rente-aanbod verloopt: hoe zien jullie dit in het dossier?',
  body:`Ik raak soms het overzicht kwijt wanneer een renteaanbod of offerte verloopt. Hoe houden jullie dat bij in de software?`,
  antwoorden:[
   {id:'vbl-044-a1',auteur:'u1',datum:'2026-03-07T04:20:00',rA:{u5:4},rAdv:{u5:4},body:`Ik maak meteen bij ontvangst van de offerte een taak met de uiterste datum, en een tweede taak een week eerder als herinnering. In het CRM kun je die taken per adviseur filteren.`},
   {id:'vbl-044-a2',auteur:'u6',datum:'2026-03-09T11:25:00',rA:{u1:5},rAdv:{u1:5},body:`Als de offerte via HDN binnenkomt, staan de geldigheidstermijnen er vaak in. Gebruik die als basis voor je taak, maar controleer de exacte termijn altijd in de offerte zelf.`}
  ]},
 {id:'vbl-045',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-09T08:55:00',views:318,tags:['bestaande hypotheek','invoer','oversluiten'],beste:'vbl-045-a1',
  titel:'Klant heeft een lopende hypotheek bij een andere tussenpersoon',
  body:`Een nieuwe klant heeft al een hypotheek via een andere tussenpersoon. Ik wil die als bestaande situatie invoeren voordat ik een oversluitadvies geef. Hoe pakken jullie dat aan in de software?`,
  antwoorden:[
   {id:'vbl-045-a1',auteur:'u4',datum:'2026-03-11T18:56:00',rA:{u1:4,u3:3},rAdv:{u1:4,u3:3},body:`Ik voer de bestaande leningdelen handmatig in op basis van het meest recente jaaroverzicht en de hypotheekakte. Let op hoofdsom, rente, rentevaste periode, aflosvorm en fiscale status per leningdeel. Ik bewaar de documenten in het dossier, zodat ik later kan laten zien waar mijn uitgangssituatie op gebaseerd is.`},
   {id:'vbl-045-a2',auteur:'u5',datum:'2026-03-12T04:32:00',rA:{u8:4,u1:3},rAdv:{u1:3},body:`Vraag ook naar de oorspronkelijke ingangsdatum van leningdelen. Dat kan van belang zijn voor de fiscale behandeling en voor de vraag welke regels van toepassing zijn. Controleer dat aan de hand van de actuele fiscale regels.`}
  ]},
 {id:'vbl-046',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-13T15:45:00',views:118,tags:['productdata','voorwaarden','geldverstrekker'],beste:'vbl-046-a2',
  titel:'Productvoorwaarden van een geldverstrekker zijn niet actueel',
  body:`Ik merk dat de productvoorwaarden in het adviespakket niet overeenkomen met wat de geldverstrekker op zijn eigen site publiceert. Welke moet ik aanhouden?`,
  antwoorden:[
   {id:'vbl-046-a1',auteur:'u6',datum:'2026-03-13T22:12:00',rA:{u7:5},rAdv:{u7:5},body:`De voorwaarden van de geldverstrekker zelf zijn leidend. Productdata in het adviespakket worden periodiek bijgewerkt, maar er kan een vertraging zitten tussen een wijziging en de update. Meld het verschil bij de support, met een verwijzing naar de bron, zodat het kan worden aangepast.`},
   {id:'vbl-046-a2',auteur:'u8',datum:'2026-03-15T23:21:00',rA:{},rAdv:{},body:`Leg in het dossier vast welke voorwaarden je hebt gehanteerd en waar je ze hebt gecontroleerd, met datum. Dat is je onderbouwing als er later vragen komen.`}
  ]},
 {id:'vbl-047',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-16T09:20:00',views:400,tags:['pensioen','inkomen','toetsing'],beste:'vbl-047-a2',
  titel:'Pensioeninkomen invoeren voor een klant die binnen tien jaar met pensioen gaat',
  body:`Mijn klant gaat binnen de looptijd met pensioen. Waar voer ik het verwachte pensioeninkomen in, zodat de berekening ook de periode na pensionering meeneemt?`,
  antwoorden:[
   {id:'vbl-047-a1',auteur:'u7',datum:'2026-03-16T18:52:00',rA:{u5:5,u3:5,u6:3,u4:5},rAdv:{u6:3},body:`Je voert het verwachte pensioeninkomen in op basis van het overzicht van het pensioenfonds en de AOW-gegevens. Gebruik bij voorkeur een actueel pensioenoverzicht en let op of bedragen bruto per jaar zijn. Bespreek met de klant dat de verwachte bedragen kunnen wijzigen.`},
   {id:'vbl-047-a2',auteur:'u5',datum:'2026-03-18T21:04:00',rA:{u7:5,u6:5,u1:4,u3:4},rAdv:{u7:5,u6:5,u3:4},body:`In het rapport laat ik de maandlasten na pensionering apart zien, zodat de klant ziet of de woonlasten dan nog te dragen zijn. Ik leg vast welke pensioenbedragen ik heb gebruikt en welk document de bron was.`}
  ]},
 {id:'vbl-048',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-20T12:20:00',views:75,tags:['rapport','standaardtekst','sjabloon'],beste:null,
  titel:'Kan ik een eigen standaardtekst toevoegen aan het rapport?',
  body:`Ik gebruik vaak dezelfde toelichting over de risico’s van een lange looptijd met aflossingsvrij leningdeel. Kan ik die als standaardtekst opslaan zodat ik hem niet steeds opnieuw hoef te typen?`,
  antwoorden:[
   {id:'vbl-048-a1',auteur:'u6',datum:'2026-03-21T19:20:00',rA:{u4:4,u3:5},rAdv:{u4:4,u3:5},body:`In eBlinqx kun je standaardteksten aanmaken en centraal beheren. Ze zijn bedoeld als basis voor e-mails en brieven, die je vanuit het dossier kunt maken. Je kiest de tekst aan de linkerkant en voegt hem toe met het plusteken. Na opslaan kun je een standaardtekst aan workflowgroepen koppelen, zodat alleen de juiste gebruikers hem zien.
Of je in het adviesrapport van eBlinqx Hypotheekadvies zelf een eigen tekstblok kunt opslaan, heb ik niet kunnen bevestigen; vraag het na via support-hypotheekadvies@blinqx.tech. Een werkbare oplossing is de toelichting op te nemen in de begeleidende brief of e-mail.
Let op: een standaardtekst over risico's van aflossingsvrij is prima als basis, maar pas hem aan op de situatie van de klant. Algemene teksten zonder koppeling aan de klant zijn een bekend aandachtspunt bij dossiercontroles.`}
  ]},
 {id:'vbl-049',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-24T17:35:00',views:108,tags:['koopsom','kosten koper','financieringsopzet'],beste:'vbl-049-a1',
  titel:'Kosten koper en eigen geld kloppen niet na wijziging koopsom',
  body:`Ik heb de koopsom in het dossier aangepast na een nieuw bod, maar de overdrachtsbelasting en het eigen geld lijken niet automatisch mee te veranderen. Moet ik iets opnieuw laten berekenen?`,
  antwoorden:[
   {id:'vbl-049-a1',auteur:'u6',datum:'2026-03-26T17:35:00',rA:{},rAdv:{},body:`Sommige posten worden automatisch herberekend, maar handmatig ingevulde bedragen blijven staan. Heb je eerder een bedrag handmatig overschreven, dan rekent het pakket daar niet meer automatisch mee. Zet die velden terug naar automatisch berekenen of pas ze bewust aan. Controleer daarna de hele financieringsopzet opnieuw.`},
   {id:'vbl-049-a2',auteur:'u1',datum:'2026-03-27T03:00:00',rA:{u8:5,u6:3},rAdv:{},body:`Controleer de overdrachtsbelasting altijd tegen de actuele regels en de situatie van de klant, bijvoorbeeld of een vrijstelling of ander tarief van toepassing is.`}
  ]},
 {id:'vbl-050',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-27T13:45:00',views:549,tags:['BKR','afwijzing','dossier'],beste:null,
  titel:'Hoe ga ik om met een afwijzing op basis van BKR in het dossier?',
  body:`De geldverstrekker wijst af vanwege een registratie die de klant niet had genoemd. Hoe leggen jullie dat vast en hoe gaan jullie verder met het advies?`,
  antwoorden:[
   {id:'vbl-050-a1',auteur:'u5',datum:'2026-03-29T03:05:00',rA:{u7:5,u2:4},rAdv:{u7:5,u2:4},body:`Ik leg de afwijzing en de reden vast in het dossier en bespreek met de klant wat er is geregistreerd. Vraag zo nodig het BKR-overzicht op en bekijk of er alternatieven zijn bij geldverstrekkers met een ander acceptatiebeleid. Controleer altijd de acceptatievoorwaarden en wees eerlijk tegen de klant over de haalbaarheid.`}
  ]},
 {id:'vbl-051',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-31T08:50:00',views:289,tags:['Finly','CRM','eBlinqx'],beste:'vbl-051-a1',
  titel:'Is Finly hetzelfde als eBlinqx CRM?',
  body:`In een webinar hoorde ik steeds Finly, maar in onze omgeving heet het eBlinqx CRM. Gaat het om hetzelfde pakket of zijn het twee verschillende producten?`,
  antwoorden:[
   {id:'vbl-051-a1',auteur:'u6',datum:'2026-04-01T07:56:00',rA:{u8:4},rAdv:{},body:`Finly is de naam die in de praktijk wordt gebruikt voor het CRM binnen eBlinqx. In schermen en documentatie kun je beide namen tegenkomen. Functioneel gaat het om dezelfde omgeving waarin je relaties, dossiers, taken en documenten beheert.`},
   {id:'vbl-051-a2',auteur:'u4',datum:'2026-04-03T06:24:00',rA:{u8:5,u5:5},rAdv:{u5:5},body:`Hetzelfde verhaal als Fastlane en eBlinqx Hypotheekadvies: oude en nieuwe namen lopen een tijd door elkaar. Zoek op de supportsite op beide namen als je iets niet vindt.`}
  ]},
 {id:'vbl-052',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-04T10:50:00',views:314,tags:['taken','backoffice','CRM'],beste:'vbl-052-a2',
  titel:'Taken toewijzen aan de backoffice in het CRM',
  body:`Ik wil taken zoals het opvragen van stukken doorzetten naar onze backoffice. Hoe richten jullie dat in, zodat ik zie wat er nog openstaat?`,
  antwoorden:[
   {id:'vbl-052-a1',auteur:'u6',datum:'2026-04-04T19:16:00',rA:{u8:4,u3:4,u4:5,u1:4},rAdv:{u3:4,u4:5,u1:4},body:`Maak de taak aan bij het dossier en wijs hem toe aan de medewerker of het team van de backoffice. Geef een duidelijke omschrijving en een vervaldatum. Via een takenoverzicht met filter op dossier of status zie je wat openstaat. Spreek af wie een taak afsluit, zodat de status klopt.`},
   {id:'vbl-052-a2',auteur:'u1',datum:'2026-04-07T09:49:00',rA:{u2:4,u3:5,u8:4,u7:4},rAdv:{u2:4,u3:5,u8:4,u7:4},body:`Wij werken met vaste taaksjablonen per fase: inventarisatie, aanvraag, offerte, passeren. Dan vergeet niemand een stap en is het werk makkelijk over te dragen bij ziekte of vakantie.`}
  ]},
 {id:'vbl-053',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-07T13:25:00',views:261,tags:['documenten','beveiliging','AVG'],beste:'vbl-053-a1',
  titel:'Documenten van de klant veilig ontvangen',
  body:`Klanten mailen mij nog vaak salarisstroken en kopieën van paspoorten. Hoe zorgen jullie dat documenten veilig binnenkomen en direct in het juiste dossier staan?`,
  antwoorden:[
   {id:'vbl-053-a1',auteur:'u8',datum:'2026-04-10T04:44:00',rA:{u6:3,u5:3,u3:4,u4:4},rAdv:{u5:3,u4:4},body:`Gebruik bij voorkeur een beveiligd klantportaal of uploadfunctie in plaats van gewone e-mail. Leg in je privacybeleid vast hoe klanten documenten aanleveren en informeer klanten daar vooraf over. Komt er toch iets per e-mail binnen, sla het dan op in het dossier en verwijder het uit je mailbox. Vraag bij een kopie identiteitsbewijs of de klant het BSN en de foto kan afschermen als dat voor jouw doel niet nodig is.`},
   {id:'vbl-053-a2',auteur:'u6',datum:'2026-04-10T10:57:00',rA:{u2:4,u4:4},rAdv:{u2:4,u4:4},body:`Als jullie omgeving een klantportaal heeft, kun je per dossier een uploadverzoek klaarzetten met de lijst van stukken. Het document komt dan direct bij de relatie binnen.`}
  ]},
 {id:'vbl-054',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-11T09:40:00',views:180,tags:['AVG','verwijderen','bewaartermijn'],beste:'vbl-054-a1',
  titel:'Relatie verwijderen op verzoek van de klant',
  body:`Een oud-klant vraagt om al zijn gegevens te verwijderen. Mag ik de relatie in het CRM gewoon wissen, of moet ik bepaalde gegevens bewaren?`,
  antwoorden:[
   {id:'vbl-054-a1',auteur:'u8',datum:'2026-04-13T03:20:00',rA:{u4:4,u7:5,u2:5,u6:4},rAdv:{u7:5,u6:4},body:`Een verwijderverzoek beoordeel je per gegevenstype. Voor dossiers met advies en bemiddeling gelden wettelijke bewaartermijnen en die gaan voor op het verwijderverzoek. Gegevens die je niet meer nodig hebt en niet hoeft te bewaren, verwijder je wel. Bevestig de klant schriftelijk wat je verwijdert en wat je bewaart, met de reden, en leg het verzoek en de afhandeling vast.`},
   {id:'vbl-054-a2',auteur:'u6',datum:'2026-04-13T22:35:00',rA:{},rAdv:{},body:`Technisch kun je in veel gevallen een relatie archiveren in plaats van verwijderen. Kijk welke opties jullie inrichting biedt en welke rechten daarvoor nodig zijn.`}
  ]},
 {id:'vbl-055',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-15T09:05:00',views:132,tags:['rentevaste periode','selectie','mailing'],beste:null,
  titel:'Mailings naar klanten met een aflopende rentevaste periode',
  body:`Ik wil klanten benaderen van wie de rentevaste periode binnen een jaar afloopt. Kan ik zo een selectie maken in het CRM en een mailing versturen?`,
  antwoorden:[
   {id:'vbl-055-a1',auteur:'u6',datum:'2026-04-16T06:33:00',rA:{},rAdv:{},body:`Als de leningdelen met de einddatum van de rentevaste periode in het CRM staan, kun je daar een selectie op maken. Exporteer of gebruik de mailfunctie, afhankelijk van wat jullie omgeving biedt. Controleer eerst of de gegevens volledig zijn, want bij oude of handmatig ingevoerde dossiers ontbreekt de einddatum soms.`},
   {id:'vbl-055-a2',auteur:'u8',datum:'2026-04-16T12:52:00',rA:{u3:3},rAdv:{u3:3},body:`Let op de grondslag voor het benaderen. Bij bestaande klanten en een dienst die aansluit bij je zorgplicht is dat meestal goed te onderbouwen, maar respecteer altijd een afmelding. Zet in iedere mailing hoe de klant zich kan afmelden.`},
   {id:'vbl-055-a3',auteur:'u1',datum:'2026-04-17T03:24:00',rA:{u6:4,u5:5,u7:5,u8:3},rAdv:{u5:5,u7:5},body:`Ik stuur geen standaard mailing maar plan per klant een belafspraak. Het gesprek over renteverlenging levert vaak ook andere vragen op.`}
  ]},
 {id:'vbl-056',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-18T09:10:00',views:51,tags:['CRM','structuur','dossier'],beste:'vbl-056-a1',
  titel:'Verschil tussen relatie, dossier en adviestraject',
  body:`Ik ben nieuw met het CRM en raak in de war van de begrippen relatie, dossier en adviestraject. Hoe gebruiken jullie die in de praktijk?`,
  antwoorden:[
   {id:'vbl-056-a1',auteur:'u6',datum:'2026-04-21T02:50:00',rA:{u8:5,u5:4},rAdv:{u8:5},body:`Een relatie is de persoon of het huishouden. Daaronder hangen een of meer dossiers, bijvoorbeeld een hypotheekadvies of een verzekeringsadvies. In een dossier leg je het adviestraject vast, met de stappen, documenten en taken. Houd per klantvraag één dossier aan; dan blijft de historie overzichtelijk.`}
  ]},
 {id:'vbl-057',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-22T16:40:00',views:10,tags:['e-mail','koppeling','CRM'],beste:null,
  titel:'Gedeelde mailbox koppelen aan het CRM',
  body:`Wij hebben een gedeelde mailbox voor hypotheekvragen. Kunnen we e-mails daaruit automatisch bij de juiste relatie opslaan?`,
  antwoorden:[
   {id:'vbl-057-a1',auteur:'u6',datum:'2026-04-24T12:40:00',rA:{u1:5,u2:5,u7:4},rAdv:{u1:5,u2:5,u7:4},body:`Ja, dat kan. De kennisbank van Finly heeft een artikel over de gedeelde mailbox. Kort:
- Een gedeelde mailbox, zoals een algemeen adres voor hypotheekvragen, kun je in het CRM koppelen zodat je vanuit één adres verstuurt en ontvangt.
- Per mailbox stel je in of e-mails automatisch aan relaties of dossiers worden gekoppeld, of dat je dat handmatig doet.
- Voor automatisch koppelen is er ook Quinn Mail. Dat koppelt alleen als de herkenning voldoende zeker is; de rest blijft over om handmatig te koppelen.
Daarvoor heb je meestal beheerrechten nodig; vragen over de inrichting kun je stellen aan support-crm@blinqx.tech. Spreek af wie de ongekoppelde mails verwerkt en controleer regelmatig of mails bij de juiste relatie staan. Een verkeerd gekoppelde mail kan een datalek zijn.`}
  ]},
 {id:'vbl-058',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-26T12:45:00',views:241,tags:['autorisatie','toegang','AVG'],beste:'vbl-058-a1',
  titel:'Wie heeft er toegang tot welk dossier?',
  body:`Op ons kantoor kan iedereen alle dossiers inzien, ook stagiairs. Is dat een probleem en hoe richten jullie rechten in?`,
  antwoorden:[
   {id:'vbl-058-a1',auteur:'u8',datum:'2026-04-27T17:12:00',rA:{},rAdv:{},body:`Volgens de AVG mag een medewerker alleen bij gegevens die hij nodig heeft voor zijn werk. Iedereen toegang geven tot alles is daarom lastig te verdedigen. Maak rollen aan, bijvoorbeeld adviseur, backoffice en stagiair, en ken per rol de rechten toe. Leg het autorisatiebeleid vast en controleer periodiek of het nog klopt.`},
   {id:'vbl-058-a2',auteur:'u6',datum:'2026-04-27T17:50:00',rA:{u4:5},rAdv:{u4:5},body:`In de beheerinstellingen kun je rollen en rechten instellen. Begin klein: eerst onderscheid maken tussen inzien en wijzigen, daarna verder verfijnen.`}
  ]},
 {id:'vbl-059',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-29T08:05:00',views:269,tags:['nazorg','klantcontact','zorgplicht'],beste:null,
  titel:'Zorgplicht na advies: periodieke check vastleggen',
  body:`Ik wil vastleggen dat ik klanten periodiek benader voor een check van hun hypotheek en verzekeringen. Hoe leggen jullie dat vast in het CRM?`,
  antwoorden:[
   {id:'vbl-059-a1',auteur:'u2',datum:'2026-04-29T20:38:00',rA:{},rAdv:{},body:`Ik plan na het passeren een terugkerende taak, bijvoorbeeld jaarlijks of bij een vast moment in het leven van de klant. Na elk contact leg ik een korte notitie vast met wat is besproken en of er actie nodig is.`},
   {id:'vbl-059-a2',auteur:'u3',datum:'2026-05-01T23:49:00',rA:{u8:4},rAdv:{},body:`Bij verzekeringen let ik vooral op wijzigingen in de situatie: geboorte, verhuizing, ander werk. Ik heb een vaste vragenlijst die ik bij elk contact doorloop en die ik als notitie opsla.`}
  ]},
 {id:'vbl-060',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-03T11:15:00',views:355,tags:['notities','dossier','klantcontact'],beste:'vbl-060-a1',
  titel:'Notitie vastleggen van een telefoongesprek',
  body:`Hoe uitgebreid leggen jullie telefoongesprekken vast? Ik twijfel of een korte notitie volstaat of dat ik meer moet opschrijven.`,
  antwoorden:[
   {id:'vbl-060-a1',auteur:'u8',datum:'2026-05-04T09:17:00',rA:{u2:5,u4:4},rAdv:{u4:4},body:`Een notitie moet laten zien wat er is besproken, welke informatie je hebt gegeven en welke afspraken zijn gemaakt. Bij adviesrelevante zaken, zoals een keuze van de klant of een gewijzigde situatie, schrijf je meer op dan bij een praktisch belletje. Vermeld datum, wie er sprak en eventuele vervolgacties.`},
   {id:'vbl-060-a2',auteur:'u1',datum:'2026-05-05T02:56:00',rA:{},rAdv:{},body:`Ik typ de notitie direct na het gesprek, dan weet ik het nog. Drie regels zijn vaak genoeg als het gaat om de kern en de afspraak.`}
  ]},
 {id:'vbl-061',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-07T16:25:00',views:546,tags:['klantportaal','inzage','documenten'],beste:null,
  titel:'Klantportaal: wat ziet de klant precies?',
  body:`We willen het klantportaal gaan gebruiken. Ik ben bang dat klanten interne notities of documenten van andere relaties kunnen zien. Hoe stellen jullie dat in?`,
  antwoorden:[
   {id:'vbl-061-a1',auteur:'u6',datum:'2026-05-08T18:13:00',rA:{u3:3,u8:5},rAdv:{u3:3,u8:5},body:`In het portaal ziet de klant alleen wat je expliciet voor hem openzet, zoals uploadverzoeken en gedeelde documenten. Interne notities horen niet zichtbaar te zijn. Test het met een eigen testrelatie voordat je live gaat, zodat je precies ziet wat de klant ziet.`},
   {id:'vbl-061-a2',auteur:'u8',datum:'2026-05-08T23:00:00',rA:{u3:5,u2:3,u7:4,u1:4},rAdv:{u3:5,u7:4,u1:4},body:`Leg in je procedure vast welke documenten je wel en niet via het portaal deelt. En let bij gezamenlijke dossiers op: zien beide partners alles, en is dat de bedoeling, bijvoorbeeld na een scheiding?`}
  ]},
 {id:'vbl-062',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-10T09:15:00',views:217,tags:['provisie','administratie','CRM'],beste:null,
  titel:'Aanvragen en provisie bijhouden in het CRM',
  body:`Ik wil per aanvraag bijhouden wanneer de provisie of de advieskosten binnen zijn. Doen jullie dat in het CRM of in een aparte administratie?`,
  antwoorden:[
   {id:'vbl-062-a1',auteur:'u2',datum:'2026-05-10T19:08:00',rA:{u4:5,u7:4,u8:4,u3:3},rAdv:{u8:4,u3:3},body:`Wij leggen de factuur en de status van betaling bij het dossier vast, maar de echte boekhouding gebeurt in het boekhoudpakket. Het CRM gebruiken we om te zien welke dossiers nog niet gefactureerd zijn.`},
   {id:'vbl-062-a2',auteur:'u6',datum:'2026-05-11T18:45:00',rA:{u4:5,u5:4,u1:4,u3:3},rAdv:{u4:5,u5:4,u1:4,u3:3},body:`Als je dit in het CRM wilt doen, gebruik dan een vast veld of status per dossier, zodat je erop kunt selecteren. Vrije tekst in notities is lastig terug te vinden.`}
  ]},
 {id:'vbl-063',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-14T11:10:00',views:495,tags:['scheiding','relatie','CRM'],beste:'vbl-063-a2',
  titel:'Gegevens van een scheiding verwerken bij een bestaande relatie',
  body:`Een stel waarvoor ik eerder een hypotheek heb geregeld gaat scheiden. Beide partners blijven klant. Hoe splitsen jullie de relatie in het CRM?`,
  antwoorden:[
   {id:'vbl-063-a1',auteur:'u6',datum:'2026-05-15T22:42:00',rA:{u7:3,u1:4,u4:4,u8:3},rAdv:{u1:4,u8:3},body:`Maak voor beide partners een eigen relatie aan en koppel het bestaande dossier aan beide. Nieuwe adviezen leg je vast in een eigen dossier per persoon. Zo blijft de historie bewaard en zien ze elkaars nieuwe gegevens niet.`},
   {id:'vbl-063-a2',auteur:'u8',datum:'2026-05-16T04:19:00',rA:{u3:4},rAdv:{u3:4},body:`Let goed op wie wat te zien krijgt, ook in het klantportaal. Leg vast welke informatie je met wie mag delen en controleer de contactgegevens, zodat post niet bij de verkeerde ex-partner terechtkomt.`},
   {id:'vbl-063-a3',auteur:'u5',datum:'2026-05-17T00:49:00',rA:{},rAdv:{},body:`Inhoudelijk is het advies bij een scheiding vaak complex. Ik adviseer ieder apart en leg in het dossier vast hoe ik met mogelijke belangenverstrengeling omga.`}
  ]},
 {id:'vbl-064',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-18T11:45:00',views:65,tags:['import','relaties','CRM'],beste:null,
  titel:'Import van relaties uit een Excel-bestand',
  body:`We stappen over van een ander systeem en hebben een export in Excel. Kunnen we die relaties in één keer in het CRM importeren?`,
  antwoorden:[
   {id:'vbl-064-a1',auteur:'u6',datum:'2026-05-19T20:45:00',rA:{u8:4,u5:5,u3:4,u2:4},rAdv:{u5:5,u3:4,u2:4},body:`Dat kan, maar een grote migratie zou ik eerst afstemmen met de CRM-support (support-crm@blinqx.tech). Uit de kennisbank van Finly:
- Het importbestand kan een Excel-bestand of een CSV in UTF-8 zijn. Met UTF-8 komen letters met accenten goed door.
- Komt het bestand uit een ander systeem, kopieer dan de inhoud en plak die in Excel als waarden. Dat verwijdert verborgen gegevens die de import kunnen blokkeren.
- Zet datumkolommen in het juiste formaat, dag-maand-jaar.
Voor groepen relaties is er ook de respondentengroep. Voor een volledige overstap met dossiers en documenten is een migratietraject vaak handiger.
Test eerst met een klein bestand, controleer op dubbelen en kijk of alle velden goed aankomen. Bewaar het exportbestand veilig en verwijder het na de migratie, want er staan veel persoonsgegevens in.`}
  ]},
 {id:'vbl-065',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-21T09:25:00',views:464,tags:['agenda','afspraak','CRM'],beste:null,
  titel:'Afspraak plannen vanuit het CRM in de agenda',
  body:`Kan ik vanuit het dossier direct een afspraak inplannen die in mijn eigen agenda verschijnt? Nu plan ik dubbel.`,
  antwoorden:[
   {id:'vbl-065-a1',auteur:'u6',datum:'2026-05-23T01:51:00',rA:{u5:5,u2:5},rAdv:{u5:5,u2:5},body:`Dat hangt af van de koppeling met jullie agenda. Als die is ingesteld, verschijnt een afspraak die je bij een relatie plant ook in je agenda. Is dat niet zo, vraag dan bij je beheerder na of de agendakoppeling beschikbaar is.`}
  ]},
 {id:'vbl-066',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-25T15:40:00',views:112,tags:['Wwft','identificatie','dossier'],beste:'vbl-066-a1',
  titel:'Wwft-identificatie vastleggen in het CRM',
  body:`Ik moet bij nieuwe klanten de identiteit vaststellen. Waar leggen jullie de controle van het identiteitsbewijs vast in het CRM?`,
  antwoorden:[
   {id:'vbl-066-a1',auteur:'u8',datum:'2026-05-27T11:15:00',rA:{u7:5},rAdv:{u7:5},body:`Leg bij de relatie vast welk document je hebt gezien, het documentnummer, de geldigheidsdatum, de datum van controle en wie de controle heeft gedaan. Bewaar een kopie alleen als dat nodig is voor jouw verplichtingen en volgens je beleid. Controleer ook of de klant in jullie risicobeoordeling valt onder verscherpt onderzoek. Leg dat apart vast.`},
   {id:'vbl-066-a2',auteur:'u6',datum:'2026-05-28T04:00:00',rA:{},rAdv:{},body:`Sommige omgevingen hebben aparte velden voor identificatie. Gebruik die en geen vrije notities, dan kun je er later op rapporteren.`}
  ]},
 {id:'vbl-067',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-28T08:20:00',views:116,tags:['legitimatie','signalering','taken'],beste:'vbl-067-a2',
  titel:'Verlopen legitimatie automatisch signaleren',
  body:`Ik zie soms pas bij de aanvraag dat het identiteitsbewijs van de klant is verlopen. Kan het CRM mij daar vooraf op wijzen?`,
  antwoorden:[
   {id:'vbl-067-a1',auteur:'u6',datum:'2026-05-29T01:11:00',rA:{u4:5,u3:5,u5:4,u8:4},rAdv:{u5:4,u8:4},body:`Als de geldigheidsdatum in een vast veld staat, kun je een selectie maken van relaties met een verlopen of bijna verlopen document. Een automatische melding is afhankelijk van jullie inrichting. Je kunt ook een taak koppelen aan de geldigheidsdatum.`},
   {id:'vbl-067-a2',auteur:'u4',datum:'2026-05-30T17:05:00',rA:{u1:3},rAdv:{u1:3},body:`Ik controleer de legitimatie altijd bij het eerste gesprek, niet pas bij de aanvraag. Dan heeft de klant nog tijd om een nieuwe aan te vragen.`}
  ]},
 {id:'vbl-068',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-01T14:35:00',views:517,tags:['bewaartermijn','archief','dossier'],beste:'vbl-068-a1',
  titel:'Hoe lang moet ik adviesdossiers bewaren?',
  body:`Ik wil oude dossiers opschonen. Hoe lang moeten jullie adviesdossiers bewaren en wat doen jullie met dossiers van klanten die nooit klant zijn geworden?`,
  antwoorden:[
   {id:'vbl-068-a1',auteur:'u8',datum:'2026-06-04T11:57:00',rA:{},rAdv:{},body:`Bewaartermijnen volgen uit verschillende regels, onder andere fiscale bewaarplicht, de Wwft en de verjaringstermijnen van mogelijke claims. Leg in je beleid per type dossier een termijn vast en motiveer die. Voor relaties die geen klant zijn geworden heb je vaak geen grond om gegevens lang te bewaren. Controleer de actuele regels of overleg met je compliance-functie.`}
  ]},
 {id:'vbl-069',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-05T13:55:00',views:78,tags:['klachten','registratie','compliance'],beste:'vbl-069-a1',
  titel:'Klachten registreren in het CRM',
  body:`We moeten klachten registreren. Doen jullie dat in het CRM of in een apart register?`,
  antwoorden:[
   {id:'vbl-069-a1',auteur:'u8',datum:'2026-06-06T04:00:00',rA:{},rAdv:{},body:`Een apart klachtenregister is overzichtelijk, maar het kan ook in het CRM als je klachten herkenbaar vastlegt, bijvoorbeeld met een eigen dossier of type. Belangrijk is dat je per klacht ziet wanneer hij binnenkwam, wat de klacht is, hoe hij is afgehandeld en binnen welke termijn. Analyseer periodiek of er patronen zijn.`},
   {id:'vbl-069-a2',auteur:'u6',datum:'2026-06-06T13:42:00',rA:{u3:5,u5:5},rAdv:{u5:5},body:`Maak in het CRM een vast dossiertype of label voor klachten. Dan kun je ze eenvoudig selecteren voor je jaarlijkse rapportage.`}
  ]},
 {id:'vbl-070',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-08T13:55:00',views:161,tags:['sessie','uitloggen','invoer'],beste:null,
  titel:'Onverwachte uitlog en verloren invoer in het CRM',
  body:`Ik word soms uitgelogd terwijl ik een lange notitie typ, en dan is de tekst weg. Hebben anderen dat ook?`,
  antwoorden:[
   {id:'vbl-070-a1',auteur:'u6',datum:'2026-06-10T07:04:00',rA:{u4:4,u2:5,u3:4,u1:5},rAdv:{u2:5,u1:5},body:`Om veiligheidsredenen word je na een periode zonder activiteit uitgelogd. Typen in een tekstveld telt niet altijd als activiteit richting de server. Sla tussentijds op of schrijf lange notities eerst in een ander programma. Merk je dat het vaker gebeurt dan je verwacht, meld het dan bij de support met tijdstip en browser.`}
  ]},
 {id:'vbl-071',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-12T09:35:00',views:46,tags:['inventarisatie','klantportaal','formulier'],beste:null,
  titel:'Inventarisatieformulier laten invullen door de klant',
  body:`Kan de klant zelf vooraf een inventarisatie invullen die ik daarna in het dossier zie? Dat bespaart tijd in het eerste gesprek.`,
  antwoorden:[
   {id:'vbl-071-a1',auteur:'u6',datum:'2026-06-13T19:35:00',rA:{u7:5,u4:5,u3:4},rAdv:{u7:5,u4:5,u3:4},body:`Ja, daar zijn een paar routes voor.
- Klantprofiel in Uwkluis: de klant vult een vragenlijst in over doelen, kennis en ervaring, financiële positie en risicobereidheid. Je start het verzoek vanuit de workflow in eBlinqx of vanuit PortefeuilleSignalen. Het ingevulde profiel komt als PDF in eBlinqx.
- Procesversneller: de klant levert digitaal de gegevens aan die nodig zijn voor een hypotheekaanvraag, die je daarna voor inventarisatie en advies kunt gebruiken.
- Brondata via Ockto voor inkomen en pensioen.
- Formulieren in Finly; bij vragen daarover kun je terecht bij support-finconnect@blinqx.tech.
Gebruik de ingevulde gegevens als voorbereiding en niet als vervanging van het gesprek. Bespreek de antwoorden met de klant, zeker over risicobereidheid en wensen, en leg vast wat je hebt gecontroleerd en aangepast.`}
  ]},
 {id:'vbl-072',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-16T15:30:00',views:115,tags:['werkgeversverklaring','inkomen','documenten'],beste:null,
  titel:'Werkgeversverklaring koppelen aan het juiste inkomen',
  body:`Mijn klant heeft twee werkgevers en dus twee werkgeversverklaringen. Hoe koppelen jullie elk document aan het juiste inkomen in het dossier?`,
  antwoorden:[
   {id:'vbl-072-a1',auteur:'u4',datum:'2026-06-17T17:55:00',rA:{u3:5,u7:4},rAdv:{},body:`Ik voer per werkgever een apart inkomen in en geef het document een duidelijke naam met de naam van de werkgever en de datum. In de notitie bij het inkomen verwijs ik naar het document. Controleer bij twee dienstverbanden ook hoe de geldverstrekker met het tweede inkomen omgaat.`},
   {id:'vbl-072-a2',auteur:'u6',datum:'2026-06-18T15:27:00',rA:{u2:4,u4:3},rAdv:{u4:3},body:`Gebruik de documentcategorie inkomen en een vaste naamgeving. Dan kan ook de backoffice snel zien welk stuk waarbij hoort.`}
  ]},
 {id:'vbl-073',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-19T13:55:00',views:326,tags:['rapport','kantoor','overdracht'],beste:'vbl-073-a1',
  titel:'Rapport overzetten naar een ander kantoor binnen dezelfde organisatie',
  body:`Een klant verhuist en wordt verder geholpen door ons andere vestiging. Kan het dossier eenvoudig worden overgezet, of moet de collega opnieuw beginnen?`,
  antwoorden:[
   {id:'vbl-073-a1',auteur:'u6',datum:'2026-06-20T07:36:00',rA:{u5:5,u2:3,u4:5,u3:5},rAdv:{u5:5,u2:3,u4:5,u3:5},body:`Als beide vestigingen in dezelfde omgeving werken, kun je de relatie en het dossier toewijzen aan een andere adviseur of vestiging. Werken ze in aparte omgevingen, dan is overzetten afhankelijk van de exportmogelijkheden. Overleg met je beheerder.`},
   {id:'vbl-073-a2',auteur:'u8',datum:'2026-06-22T11:28:00',rA:{},rAdv:{},body:`Informeer de klant dat zijn dossier wordt overgedragen en leg dat vast. De nieuwe adviseur moet zelf controleren of de gegevens nog actueel zijn voordat hij verder adviseert.`}
  ]},
 {id:'vbl-074',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-23T14:25:00',views:567,tags:['advieskosten','opdrachtbevestiging','transparantie'],beste:'vbl-074-a1',
  titel:'Kosten voor advies en bemiddeling laten zien in het CRM',
  body:`Ik wil dat in het dossier zichtbaar is welke kosten we met de klant hebben afgesproken. Waar leggen jullie de opdracht tot dienstverlening vast?`,
  antwoorden:[
   {id:'vbl-074-a1',auteur:'u8',datum:'2026-06-24T06:55:00',rA:{},rAdv:{},body:`Leg de getekende opdracht tot dienstverlening (opdrachtbevestiging) bij de relatie of het dossier vast, samen met de versie van de vergelijkingskaart die de klant vooraf heeft gekregen. Daarin staan de afgesproken diensten en kosten. Bij een wijziging van de opdracht leg je ook de nieuwe afspraak vast, getekend of aantoonbaar akkoord.`},
   {id:'vbl-074-a2',auteur:'u2',datum:'2026-06-25T11:00:00',rA:{u3:4,u8:3},rAdv:{u3:4,u8:3},body:`Ik zet het afgesproken bedrag ook in een vast veld, zodat ik bij het factureren niet het document hoef te openen.`}
  ]},
 {id:'vbl-075',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-27T14:00:00',views:501,tags:['datalek','AVG','rapport'],beste:'vbl-075-a1',
  titel:'Melding datalek: verkeerde klant kreeg een rapport',
  body:`Een collega heeft per ongeluk een adviesrapport naar de verkeerde klant gestuurd. Wat moeten we nu doen en hoe voorkomen we het in de software?`,
  antwoorden:[
   {id:'vbl-075-a1',auteur:'u8',datum:'2026-06-30T02:36:00',rA:{},rAdv:{},body:`Behandel het als een mogelijk datalek. Vraag de ontvanger het bericht te verwijderen en dat te bevestigen. Beoordeel of het lek gemeld moet worden bij de toezichthouder en of de betrokken klant geïnformeerd moet worden, en registreer het incident altijd in je datalekregister. Doe dit snel, want voor een melding geldt een korte termijn.`},
   {id:'vbl-075-a2',auteur:'u6',datum:'2026-06-30T05:02:00',rA:{u7:4,u8:3,u3:4,u1:4},rAdv:{u7:4,u3:4},body:`Om herhaling te voorkomen: verstuur rapporten bij voorkeur via het klantportaal of vanuit het dossier, zodat het e-mailadres van de relatie wordt gebruikt. Handmatig adressen invullen is de grootste foutbron.`}
  ]},
 {id:'vbl-076',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-30T13:10:00',views:419,tags:['rapport','leesbaarheid','klant'],beste:'vbl-076-a1',
  titel:'Adviesrapport is te lang voor de klant',
  body:`Het standaard adviesrapport uit het pakket is tientallen pagina's lang. Klanten lezen het niet. Hoe maken jullie het rapport korter zonder dat er verplichte onderdelen ontbreken?`,
  antwoorden:[
   {id:'vbl-076-a1',auteur:'u5',datum:'2026-07-01T17:28:00',rA:{u1:4,u4:4},rAdv:{u1:4},body:`Ik zet een samenvatting van een of twee pagina's vooraan met het advies, de maandlasten en de belangrijkste risico’s. De uitgebreide onderbouwing blijft in het rapport, maar de klant weet waar hij moet beginnen. Bespreek het rapport ook mondeling door.`},
   {id:'vbl-076-a2',auteur:'u8',datum:'2026-07-02T19:21:00',rA:{u2:4,u1:4,u3:5,u5:3},rAdv:{u2:4,u1:4},body:`Schrap geen onderdelen die je nodig hebt om aan te tonen dat het advies passend is, zoals de inventarisatie, de risicoanalyse en de motivatie. Een kortere presentatie mag, een onvollediger dossier niet.`},
   {id:'vbl-076-a3',auteur:'u6',datum:'2026-07-03T05:25:00',rA:{u7:5,u2:5,u3:3},rAdv:{u7:5,u3:3},body:`In de rapportinstellingen kun je vaak hoofdstukken of bijlagen in- en uitschakelen. Kijk welke onderdelen standaard aan staan en of ze voor jouw adviezen relevant zijn.`}
  ]},
 {id:'vbl-077',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-04T08:15:00',views:298,tags:['motivatie','rapport','passend advies'],beste:'vbl-077-a1',
  titel:'Motivatie van het advies: hoe uitgebreid?',
  body:`Het adviespakket heeft een motivatieveld per onderdeel. Hoe uitgebreid vullen jullie dat in? Ik zie collega's die alleen standaardzinnen gebruiken.`,
  antwoorden:[
   {id:'vbl-077-a1',auteur:'u8',datum:'2026-07-05T12:11:00',rA:{u7:3},rAdv:{u7:3},body:`Standaardzinnen zijn een bekend aandachtspunt bij dossiercontroles. De motivatie moet laten zien waarom dit advies past bij deze klant, met verwijzing naar zijn situatie, wensen en risicobereidheid. Een paar zinnen die echt op de klant ingaan zijn beter dan een lange algemene tekst.`},
   {id:'vbl-077-a2',auteur:'u5',datum:'2026-07-05T18:05:00',rA:{u2:5},rAdv:{},body:`Ik gebruik een vaste opbouw: wat wil de klant, wat heb ik geadviseerd, waarom, en welke alternatieven heb ik overwogen. Dat dwingt me om per klant na te denken.`},
   {id:'vbl-077-a3',auteur:'u1',datum:'2026-07-06T05:44:00',rA:{},rAdv:{},body:`Tip: schrijf de motivatie direct na het adviesgesprek, dan weet je nog wat de klant belangrijk vond.`}
  ]},
 {id:'vbl-078',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-08T09:10:00',views:232,tags:['rapport','prestaties','PDF'],beste:null,
  titel:'Rapport genereren duurt erg lang',
  body:`Het aanmaken van het adviesrapport duurt soms minuten. Ligt dat aan mijn computer of aan de software?`,
  antwoorden:[
   {id:'vbl-078-a1',auteur:'u6',datum:'2026-07-08T23:16:00',rA:{u7:4,u8:5},rAdv:{},body:`Rapporten worden meestal op de server gemaakt, dus je computer is zelden de oorzaak. Lange rapporten met veel bijlagen of grafieken duren langer. Komt het structureel voor, meld het dan bij de support met het tijdstip en het dossier, zodat ze kunnen kijken of er een probleem is.`}
  ]},
 {id:'vbl-079',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-11T16:55:00',views:23,tags:['rapport','Engels','expat'],beste:null,
  titel:'Rapport in het Engels voor een expat',
  body:`Ik adviseer een expat die geen Nederlands spreekt. Kan ik het adviesrapport in het Engels laten maken?`,
  antwoorden:[
   {id:'vbl-079-a1',auteur:'u6',datum:'2026-07-13T04:55:00',rA:{u3:4,u8:5,u7:4,u2:4},rAdv:{u3:4,u7:4,u2:4},body:`In eBlinqx kun je per persoon een voorkeurstaal instellen, Nederlands of Engels. Workflows kunnen daarop reageren, zodat bijvoorbeeld conceptmails in het Engels klaarstaan, en de voortgang in Uwkluis wordt dan in het Engels getoond.
Of het adviesrapport uit eBlinqx Hypotheekadvies volledig in het Engels kan worden gemaakt, heb ik niet kunnen bevestigen. Vraag het na via support-hypotheekadvies@blinqx.tech voordat je de klant iets toezegt. Een alternatief is een Engelstalige toelichting naast het Nederlandse rapport.
Belangrijk is dat de klant het advies begrijpt. Bespreek het rapport mondeling in het Engels en leg vast in welke taal je het hebt besproken. Let op dat offerte en akte meestal in het Nederlands zijn. Bij de notaris kan een tolk nodig zijn; stem dat op tijd af.`}
  ]},
 {id:'vbl-080',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-15T15:40:00',views:318,tags:['grafiek','maandlasten','rapport'],beste:null,
  titel:'Grafiek met maandlasten over de looptijd klopt niet met de tabel',
  body:`In het rapport zie ik een grafiek van de netto maandlasten die niet overeenkomt met de tabel. Welke klopt er?`,
  antwoorden:[
   {id:'vbl-080-a1',auteur:'u6',datum:'2026-07-17T22:27:00',rA:{u3:5,u5:4},rAdv:{u3:5},body:`Controleer of grafiek en tabel over dezelfde periode en dezelfde lasten gaan. Soms toont de grafiek bruto lasten en de tabel netto, of zit er een verschil in welke leningdelen zijn meegenomen. Als het echt niet overeenkomt, meld het met een voorbeeld bij de support.`},
   {id:'vbl-080-a2',auteur:'u1',datum:'2026-07-18T02:07:00',rA:{u3:5,u6:4,u2:4},rAdv:{u6:4,u2:4},body:`Ik leg altijd de tabel uit aan de klant en gebruik de grafiek alleen als illustratie. De tabel is makkelijker te controleren.`}
  ]},
 {id:'vbl-081',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-19T15:20:00',views:558,tags:['aflossingsvrij','restschuld','risico'],beste:'vbl-081-a1',
  titel:'Aflossingsvrij deel en risico van restschuld in het rapport',
  body:`Hoe laten jullie in het rapport zien welke schuld er aan het einde van de looptijd overblijft bij een aflossingsvrij leningdeel?`,
  antwoorden:[
   {id:'vbl-081-a1',auteur:'u5',datum:'2026-07-21T14:29:00',rA:{u4:4,u1:5,u2:5},rAdv:{u4:4,u1:5},body:`Ik laat per leningdeel zien wat de schuld is aan het einde van de looptijd en bespreek hoe de klant die wil oplossen, bijvoorbeeld met vermogen of verkoop van de woning. Ook laat ik zien wat dit betekent bij pensioen. De keuze en de toelichting leg ik vast in de motivatie.`},
   {id:'vbl-081-a2',auteur:'u2',datum:'2026-07-22T06:13:00',rA:{u4:4},rAdv:{},body:`In een financieel plan zet ik daarnaast een overzicht van het verwachte vermogen. Zo kan de klant zien of hij de restschuld realistisch kan aflossen.`}
  ]},
 {id:'vbl-082',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-22T11:40:00',views:188,tags:['risicoanalyse','rapport','overlijden'],beste:'vbl-082-a1',
  titel:'Verplichte risicoparagrafen: welke laten jullie altijd zien?',
  body:`Welke risico's nemen jullie standaard op in het adviesrapport bij een hypotheekadvies?`,
  antwoorden:[
   {id:'vbl-082-a1',auteur:'u3',datum:'2026-07-25T07:33:00',rA:{u8:4,u2:4},rAdv:{u8:4},body:`Ik behandel standaard overlijden, arbeidsongeschiktheid, werkloosheid, pensionering en relatiebeëindiging. Bij elk risico laat ik zien wat het gevolg is voor de maandlasten en wat de mogelijke oplossingen zijn.`},
   {id:'vbl-082-a2',auteur:'u8',datum:'2026-07-25T09:37:00',rA:{u4:4,u5:4,u1:5},rAdv:{u5:4,u1:5},body:`Laat ook zien welke risico's de klant bewust accepteert en waarom. Dat is net zo belangrijk als de risico's die je afdekt.`}
  ]},
 {id:'vbl-083',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-26T11:20:00',views:548,tags:['ORV','overlijdensrisico','berekening'],beste:'vbl-083-a1',
  titel:'Overlijdensrisicoverzekering koppelen aan het leningdeel',
  body:`Ik adviseer een overlijdensrisicoverzekering. Hoe zorg ik dat de berekening laat zien dat het tekort na overlijden is opgelost?`,
  antwoorden:[
   {id:'vbl-083-a1',auteur:'u3',datum:'2026-07-27T00:26:00',rA:{u5:3},rAdv:{u5:3},body:`Voer de verzekering in bij de risicoanalyse, met verzekerd bedrag, looptijd en verzekerde personen. De berekening laat dan zien of het tekort na overlijden is afgedekt. Let erop of het bedrag gelijkblijvend of dalend is en of dat past bij de leningdelen.`},
   {id:'vbl-083-a2',auteur:'u6',datum:'2026-07-29T03:07:00',rA:{u2:4},rAdv:{u2:4},body:`Controleer na het invoeren of de verzekering echt aan het juiste dossier is gekoppeld. Een product dat alleen in het CRM staat, wordt niet automatisch meegenomen in de risicoanalyse.`}
  ]},
 {id:'vbl-084',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-29T08:55:00',views:330,tags:['concept','rapport','klant'],beste:null,
  titel:'Rapport delen met de klant voordat het definitief is',
  body:`Ik wil de klant eerst een concept laten lezen. Hoe markeren jullie een conceptrapport zodat er geen verwarring ontstaat?`,
  antwoorden:[
   {id:'vbl-084-a1',auteur:'u1',datum:'2026-07-29T15:00:00',rA:{},rAdv:{},body:`Ik zet duidelijk concept in de bestandsnaam en bespreek het in een gesprek. Het definitieve rapport laat ik pas ondertekenen als alles klopt.`},
   {id:'vbl-084-a2',auteur:'u8',datum:'2026-08-01T04:41:00',rA:{u7:5,u2:5},rAdv:{},body:`Bewaar zowel het concept als de definitieve versie in het dossier als er inhoudelijke verschillen zijn. Dan kun je laten zien hoe het advies tot stand is gekomen.`}
  ]},
 {id:'vbl-085',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-02T17:40:00',views:244,tags:['inloggen','wachtwoord','tweestapsverificatie'],beste:'vbl-085-a1',
  titel:'Geen toegang meer na wachtwoordreset',
  body:`Na een wachtwoordreset kan ik niet meer inloggen omdat de tweestapsverificatie op mijn oude telefoon staat. Wat nu?`,
  antwoorden:[
   {id:'vbl-085-a1',auteur:'u6',datum:'2026-08-03T09:17:00',rA:{u2:5,u8:4},rAdv:{u2:5},body:`Neem contact op met je eigen beheerder of de support. Zij kunnen de tweestapsverificatie voor jouw account opnieuw instellen nadat je identiteit is gecontroleerd. Stel daarna direct de verificatie op je nieuwe telefoon in en bewaar herstelcodes op een veilige plek.`}
  ]},
 {id:'vbl-086',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-06T17:50:00',views:71,tags:['samenwerken','dossier','rechten'],beste:'vbl-086-a1',
  titel:'Meerdere adviseurs werken aan hetzelfde dossier',
  body:`Een collega en ik werken samen aan een dossier. Soms overschrijven we elkaars wijzigingen. Hoe gaan jullie daarmee om?`,
  antwoorden:[
   {id:'vbl-086-a1',auteur:'u6',datum:'2026-08-06T20:28:00',rA:{},rAdv:{},body:`Spreek af wie op welk moment aan het dossier werkt. Twee mensen die tegelijk in hetzelfde scherm wijzigen is een bekende oorzaak van overschreven gegevens. Sla tussentijds op en vernieuw het scherm voordat je verder gaat.`},
   {id:'vbl-086-a2',auteur:'u1',datum:'2026-08-08T14:10:00',rA:{u8:5,u7:3},rAdv:{u7:3},body:`Wij werken met een vaste eigenaar per dossier. De collega doet wijzigingen alleen na overleg en zet dat in een notitie.`}
  ]},
 {id:'vbl-087',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-09T11:00:00',views:23,tags:['vergelijken','rapport','scenario'],beste:null,
  titel:'Gegevens uit de Berekening vergelijken naar het rapport',
  body:`Ik heb drie berekeningen vergeleken. Kan ik dat vergelijkingsoverzicht in het rapport opnemen?`,
  antwoorden:[
   {id:'vbl-087-a1',auteur:'u6',datum:'2026-08-11T08:00:00',rA:{u3:5,u7:5},rAdv:{u3:5,u7:5},body:`Ja. Open de berekening, klik rechtsboven op Berekeningen vergelijken en daarna op het PDF-icoon. Dan maak je een PDF met de varianten naast elkaar.
Of dat overzicht automatisch als hoofdstuk in het adviesrapport komt, verschilt; ik voeg het meestal als bijlage toe aan het rapport en sla het op in het dossier.
Tips:
- Geef de varianten een duidelijke naam, bijvoorbeeld met de rentevaste periode of de aflosvorm erin.
- Beperk je tot de varianten die je echt hebt besproken.
- Leg in het rapport uit waarom je de gekozen variant adviseert en waarom de andere minder goed passen.
Bewaar de vergelijking die de klant heeft gezien, met de datum, in het dossier.`}
  ]},
 {id:'vbl-088',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-13T16:50:00',views:447,tags:['afwijkende keuze','rapport','vastleggen'],beste:'vbl-088-a1',
  titel:'Klant kiest een ander product dan geadviseerd',
  body:`De klant kiest uiteindelijk voor een langere rentevaste periode dan ik had geadviseerd. Moet ik het rapport aanpassen?`,
  antwoorden:[
   {id:'vbl-088-a1',auteur:'u8',datum:'2026-08-14T19:42:00',rA:{u6:3},rAdv:{u6:3},body:`Ja, leg in het rapport en het dossier vast dat de klant afwijkt van het advies, wat de gevolgen zijn en dat de klant die gevolgen begrijpt. Laat de klant dat bij voorkeur bevestigen. Een afwijkende keuze is toegestaan, maar moet aantoonbaar een geïnformeerde keuze zijn.`},
   {id:'vbl-088-a2',auteur:'u5',datum:'2026-08-15T15:16:00',rA:{},rAdv:{},body:`Bij een langere rentevaste periode vind ik het vaak juist goed te verdedigen. Pas in dat geval ook je eigen motivatie aan als je het eigenlijk met de klant eens bent.`}
  ]},
 {id:'vbl-089',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-17T13:35:00',views:123,tags:['energielabel','woning','invoer'],beste:'vbl-089-a1',
  titel:'Kenmerken van de woning: energielabel invoeren',
  body:`Waar voer ik het energielabel van de woning in en heeft het invloed op de berekening?`,
  antwoorden:[
   {id:'vbl-089-a1',auteur:'u6',datum:'2026-08-18T09:46:00',rA:{u8:4,u1:5},rAdv:{u8:4,u1:5},body:`Het energielabel voer je in bij de gegevens van het onderpand. Het kan invloed hebben op de leencapaciteit, omdat de leennormen voor bepaalde labels extra ruimte geven voor energiebesparende maatregelen. Controleer de actuele normen en de voorwaarden van de geldverstrekker.`},
   {id:'vbl-089-a2',auteur:'u4',datum:'2026-08-19T01:55:00',rA:{u1:4,u6:5},rAdv:{u6:5},body:`Neem het label over van een geldig energielabel of het taxatierapport, niet van wat de verkoper zegt. Bewaar het bewijs in het dossier.`}
  ]},
 {id:'vbl-090',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-20T15:10:00',views:248,tags:['verhoging','aanvraag','bestaande hypotheek'],beste:null,
  titel:'Aanvraag maken voor een bestaande klant die extra leent',
  body:`Mijn klant wil een verhoging van zijn hypotheek bij dezelfde geldverstrekker. Kan ik dat ook via HDN aanvragen of moet ik het rechtstreeks regelen?`,
  antwoorden:[
   {id:'vbl-090-a1',auteur:'u4',datum:'2026-08-21T04:49:00',rA:{u7:4,u6:5,u8:5,u3:4},rAdv:{u7:4,u6:5,u8:5},body:`Dat verschilt per geldverstrekker. Bij een deel kan een verhoging via HDN worden aangevraagd, bij andere moet het via hun eigen portaal. Controleer de werkwijze bij de geldverstrekker. Voor je advies maakt het niet uit: je doet een volledige inventarisatie van de gewijzigde situatie.`}
  ]},
 {id:'vbl-091',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-24T13:00:00',views:125,tags:['update','berekening','normen'],beste:'vbl-091-a2',
  titel:'Software-update: berekening geeft ineens andere uitkomst',
  body:`Na een update geeft dezelfde berekening een iets ander maximaal leenbedrag. Ik had het rapport al met de klant besproken. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbl-091-a1',auteur:'u6',datum:'2026-08-25T12:01:00',rA:{u4:5,u7:5,u8:4},rAdv:{u4:5,u8:4},body:`Updates kunnen nieuwe normen, rekenregels of productdata bevatten. Bij een jaarwisseling of normwijziging is een andere uitkomst dus te verwachten. Kijk in de releasenotes wat er is veranderd.`},
   {id:'vbl-091-a2',auteur:'u5',datum:'2026-08-25T13:32:00',rA:{u2:3,u8:5,u4:5,u1:4},rAdv:{u2:3,u1:4},body:`Bespreek het verschil met de klant als het van invloed is op het advies. Leg vast met welke normen het oorspronkelijke advies is gemaakt en waarom je het eventueel aanpast.`}
  ]},
 {id:'vbl-092',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-28T17:40:00',views:471,tags:['box 3','vermogen','rapport'],beste:null,
  titel:'Box 3-leningdeel en vermogen in het rapport',
  body:`Mijn klant heeft een leningdeel in box 3 omdat het geld deels voor een andere besteding wordt gebruikt. Hoe laten jullie dat zien in het rapport?`,
  antwoorden:[
   {id:'vbl-092-a1',auteur:'u2',datum:'2026-08-30T06:58:00',rA:{},rAdv:{},body:`Ik laat het box 3-deel apart zien en leg uit dat de rente niet aftrekbaar is in box 1. In het financieel overzicht neem ik de schuld mee in box 3. Voor de actuele fiscale behandeling verwijs ik naar de geldende regels.`},
   {id:'vbl-092-a2',auteur:'u6',datum:'2026-08-31T17:08:00',rA:{u2:3,u1:3,u5:3,u3:4},rAdv:{u1:3},body:`In de berekening kun je per leningdeel aangeven of het in box 1 of box 3 valt. Controleer na het genereren of het rapport dat onderscheid goed toont.`}
  ]},
 {id:'vbl-093',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-31T13:50:00',views:546,tags:['pijplijn','rapportage','management'],beste:null,
  titel:'Overzicht van alle lopende aanvragen per adviseur',
  body:`Als teamleider wil ik zien hoeveel aanvragen er per adviseur lopen en in welke fase. Kan dat uit het CRM?`,
  antwoorden:[
   {id:'vbl-093-a1',auteur:'u6',datum:'2026-09-02T15:04:00',rA:{},rAdv:{},body:`Als de fases consequent worden bijgehouden, kun je een overzicht maken per adviseur en per status. Begin met heldere afspraken over welke status wanneer wordt gezet, anders klopt het overzicht niet.`}
  ]},
 {id:'vbl-094',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-04T16:50:00',views:599,tags:['samenwerking','inzage','AVG'],beste:'vbl-094-a1',
  titel:'Samenwerkende partner: hoeveel inzage mag ik geven?',
  body:`Wij werken samen met een makelaar die graag wil weten hoe ver de financiering is. Mag ik hem inzage geven in het dossier of de status?`,
  antwoorden:[
   {id:'vbl-094-a1',auteur:'u8',datum:'2026-09-05T10:46:00',rA:{u3:3,u4:5},rAdv:{u3:3,u4:5},body:`Alleen met toestemming van de klant, en beperkt tot wat de makelaar nodig heeft, zoals de status van het financieringsvoorbehoud. Geef geen inzage in het hele dossier. Leg de toestemming en de afspraken vast.`},
   {id:'vbl-094-a2',auteur:'u1',datum:'2026-09-05T18:45:00',rA:{u6:5,u2:3},rAdv:{u2:3},body:`Ik vraag bij de start van het traject of ik de makelaar op de hoogte mag houden en welke informatie. Dat zet ik in het dossier.`}
  ]},
 {id:'vbl-095',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-08T11:15:00',views:584,tags:['taxatie','documenten','dossier'],beste:'vbl-095-a1',
  titel:'Hoe bewaar ik een ontvangen taxatierapport?',
  body:`Het taxatierapport komt binnen via een validatie-instituut. Waar bewaren jullie het en wat controleren jullie?`,
  antwoorden:[
   {id:'vbl-095-a1',auteur:'u4',datum:'2026-09-11T10:24:00',rA:{u5:3},rAdv:{u5:3},body:`Ik sla het taxatierapport op bij het dossier in de documentcategorie onderpand. Ik controleer of de marktwaarde overeenkomt met wat ik in de berekening heb gebruikt en of het rapport is gevalideerd als de geldverstrekker dat eist. Bij afwijkingen pas ik de berekening aan en bespreek ik het met de klant.`}
  ]},
 {id:'vbl-096',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-11T14:05:00',views:52,tags:['inzageverzoek','AVG','export'],beste:null,
  titel:'Klant wil alle gegevens ontvangen die we bewaren',
  body:`Een klant doet een inzageverzoek. Kan ik alle gegevens die we over hem hebben makkelijk uit het CRM halen?`,
  antwoorden:[
   {id:'vbl-096-a1',auteur:'u6',datum:'2026-09-12T15:05:00',rA:{u5:4,u4:5,u8:5},rAdv:{u5:4,u4:5},body:`Volgens de AVG-veelgestelde vragen van eBlinqx kun je in het klantdossier een samenvatting afdrukken voor een inzageverzoek, en kun je alle klantgegevens exporteren. Met de dossiergeschiedenis onder Dossieropties zie je ook wie het dossier heeft geopend en waar het naartoe is gestuurd.
Let op dat er vaak ook gegevens buiten het CRM staan:
- in het adviespakket of een gekoppeld pakket zoals Adviesbox;
- in mailboxen;
- in papieren archieven of netwerkmappen.
Loop die bronnen ook na. Controleer de identiteit van de aanvrager voordat je iets verstuurt en gebruik een beveiligde manier van versturen.`},
   {id:'vbl-096-a2',auteur:'u8',datum:'2026-09-12T20:05:00',rA:{u2:5,u4:4,u5:5,u1:4},rAdv:{u2:5,u4:4,u5:5,u1:4},body:`Vanuit compliance: je moet binnen een maand reageren, met een mogelijke verlenging bij complexe verzoeken. Informeer de klant dan wel binnen die maand. De klant heeft recht op een kopie van zijn persoonsgegevens, de doelen van de verwerking, de ontvangers en de bewaartermijn.
- Registreer het verzoek met datum en termijn.
- Stel vast welke systemen je moet doorzoeken.
- Interne aantekeningen en gegevens van anderen, zoals een ex-partner, beoordeel je apart voordat je ze verstrekt.
Leg vast wat je hebt verstrekt, wanneer en hoe. Bewaar dat bij de relatie.`}
  ]},
 {id:'vbl-097',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-15T16:05:00',views:239,tags:['migratie','nieuwe versie','training'],beste:'vbl-097-a1',
  titel:'Overgang naar nieuwe versie van het adviespakket',
  body:`Ons kantoor gaat over naar een nieuwe versie van het adviespakket. Hoe hebben jullie de overgang voorbereid?`,
  antwoorden:[
   {id:'vbl-097-a1',auteur:'u6',datum:'2026-09-17T19:52:00',rA:{},rAdv:{},body:`Plan vooraf een korte training en laat iedereen eerst met een testdossier werken. Controleer na de overgang een paar lopende dossiers op volledigheid. Maak een lijst met vragen en verzamel die centraal, dan kun je ze in één keer met de support bespreken.`},
   {id:'vbl-097-a2',auteur:'u1',datum:'2026-09-18T03:39:00',rA:{},rAdv:{},body:`Wij hebben een paar weken dubbel gecontroleerd: nieuwe berekening naast de oude. Dat gaf vertrouwen.`}
  ]},
 {id:'vbl-098',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-19T10:20:00',views:50,tags:['meerdere panden','dossier','berekening'],beste:null,
  titel:'Hypotheekadvies voor twee panden in één dossier',
  body:`Mijn klant heeft een eigen woning en een tweede woning. Kan ik beide in één dossier opnemen?`,
  antwoorden:[
   {id:'vbl-098-a1',auteur:'u6',datum:'2026-09-20T23:20:00',rA:{u3:5,u5:5,u4:5,u1:5},rAdv:{u3:5,u5:5,u4:5,u1:5},body:`In het CRM is dat geen probleem: je kunt bij één relatie meerdere dossiers of producten vastleggen. Ik zou per onderpand een eigen dossier of in elk geval een eigen berekening aanhouden, omdat het om aparte financieringen gaat met een eigen onderpand, een eigen fiscale behandeling en vaak een eigen aanvraag.
Of je in eBlinqx Hypotheekadvies meerdere onderpanden in één berekening kunt opnemen, heb ik niet kunnen bevestigen. Vraag het na via support-hypotheekadvies@blinqx.tech.
Inhoudelijk: neem de lasten van de tweede woning mee als verplichting bij de toetsing van de eigen woning, en andersom. Let ook op het onderscheid tussen box 1 en box 3. Leg in het dossier vast hoe je beide financieringen in samenhang hebt beoordeeld.`}
  ]},
 {id:'vbl-099',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-22T14:15:00',views:453,tags:['partner','inkomen','invoer'],beste:'vbl-099-a1',
  titel:'Gezamenlijk dossier wanneer één partner geen inkomen heeft',
  body:`Een van de aanvragers heeft geen inkomen. Moet ik die persoon toch volledig invoeren als aanvrager?`,
  antwoorden:[
   {id:'vbl-099-a1',auteur:'u5',datum:'2026-09-23T18:34:00',rA:{u2:4},rAdv:{u2:4},body:`Als beiden de hypotheek aangaan, voer je beide aanvragers in, ook als een van de twee geen inkomen heeft. Dat is nodig voor de risicoanalyse en voor de aanvraag. Controleer bij de geldverstrekker of er bijzondere voorwaarden gelden.`},
   {id:'vbl-099-a2',auteur:'u3',datum:'2026-09-24T19:14:00',rA:{},rAdv:{},body:`Vergeet niet dat ook een partner zonder inkomen relevant is voor de risico's, bijvoorbeeld bij overlijden van de kostwinner.`}
  ]},
 {id:'vbl-100',cat:'adv',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-26T08:55:00',views:189,tags:['handleiding','support','hulp'],beste:'vbl-100-a1',
  titel:'Waar vind ik de handleiding van het adviespakket?',
  body:`Ik ben nieuw met het adviespakket. Waar vinden jullie de handleiding en antwoorden op veelgestelde vragen?`,
  antwoorden:[
   {id:'vbl-100-a1',auteur:'u6',datum:'2026-09-29T00:39:00',rA:{u8:5,u2:5,u4:3,u3:5},rAdv:{u8:5,u4:3},body:`De supportsite van het pakket heeft artikelen per onderwerp en zoekfunctie. Zoek op meerdere namen, bijvoorbeeld zowel de oude als de nieuwe productnaam. Vind je het niet, stel je vraag dan bij de support of hier op het forum.`}
  ]}
]);
